(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0035.js"] = [{"id":"poem-e459b8ca6e77c43515deba68","title":"容南道中二首  其一","author":"李纲","dynasty":"宋","verses":["路入容南境，风烟自一方。","山空云苒苒，春动水茫茫。","紫府丹砂秘，幽村碧树芳。","肃然有佳致，作个是炎荒。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-9ea5d033-cb8d-45c5-ac0f-e2354538604e","tags":[]},{"id":"poem-e45da04d43e1b33e7cec874a","title":"江南杂题三十首 其八","author":"张祜","dynasty":"唐","verses":["村桥路不端，数里就回湍。","积壤连泾脉，高林上笋竿。","早尝甘蔗淡，生摘琵琶酸。","（「琵琶」，严寿澄校《张祜诗集》云：疑「枇杷」之误。","）好是去尘俗，烟花长一栏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-7f4564e4-ccb7-47b0-9bf9-d87dc5c022f8","tags":[]},{"id":"poem-e4600dedbb866cdbff91c1b6","title":"送从翁中丞奉使黠戛斯六首 一","author":"赵嘏","dynasty":"唐","verses":["扬雄词赋举天闻，万里油幢照塞云。","仆射峰西几千骑，一时迎著汉将军。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-120086c5-198f-4ce9-9c10-15f2892f1f63","tags":[]},{"id":"poem-e46574bc9a53f7598d3ea520","title":"赠乔侍郎","author":"陈子昂","dynasty":"唐","verses":["汉廷荣巧宦，云阁薄边功。","可怜骢马使，白首为谁雄。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-贈喬侍郎","tags":[]},{"id":"poem-e47100a3f78a53f25d648cc2","title":"菩萨蛮·人间何处难忘酒","author":"张抡","dynasty":"宋","verses":["人间何处难忘酒。","中秋皓月明如昼。","银汉洗晴空。","清辉万古同。","凉风生玉宇。","只怕云来去。","一盏此时迟。","阴晴未可知。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-955","tags":[]},{"id":"poem-e4754388d007dd9f39e9f9d8","title":"叙事寄荐福栖白","author":"李洞","dynasty":"唐","verses":["险倚石屏风，秋涛梦越中。","前朝吟会散，故国讲流终。","北地闻巴狖，南山见碛鸿。","楼高惊雨阔，木落觉城空。","兔满期姚监，蝉稀别楚公。","净缾光照客，拄杖朽生虫。","平地塔千尺，半空灯一笼。","祝尧谈几句，旋泻海涛东。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8f84a4f0-2c45-4e99-85a9-dcb7eb6ffcad","tags":[]},{"id":"poem-e480b1ad7c480412caea2feb","title":"寄张籍","author":"孟郊","dynasty":"唐","verses":["夜镜不照物，朝光何时升。","黯然秋思来，走入志士膺。","志士惜时逝，一宵三四兴。","清汉徒自朗，浊河终无澄。","旧爱忽已远，新愁坐相凌。","君其隐壮怀，我亦逃名称。","古人贵从晦，君子忌党朋。","倾败生所竞，保全归懵懵。","浮云何当来，潜虬会飞腾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-a8e9ed33-399c-4995-aae0-e0209c3eff2e","tags":[]},{"id":"poem-e481a86ed3b888e5627d835a","title":"塞上  其一","author":"谭用之","dynasty":"宋","verses":["秋风汉北雁飞天，单骑那堪遶贺兰。","碛暗更无岩树影，地平时有野烧瘢。","貂披寒色和衣冷，剑佩胡霜隔匣寒。","早晚横戈似飞尉，拥旄深入异田单。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-2a3d9878-990e-4711-9fd6-84a6059f076e","tags":[]},{"id":"poem-e4822f904416b4cd44203dd0","title":"梦江南·红绣被","author":"牛峤","dynasty":"五代","verses":["红绣被，两两间鸳鸯。","不是鸟中偏爱尔，为缘交颈睡南塘，全胜薄情郎。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-5","tags":[]},{"id":"poem-e48369203d0598b9fcffc6a8","title":"詶包佶郎中览拙卷后见寄","author":"卢纶","dynasty":"唐","verses":["令伯支离晚读书，岂知词赋称相如。","枉逢花木无新思，拙就溪潭损旧居。","禁路看山歌自缓，云司玩月漏应疎。","沈忧敢望金门召，空媿巴歈并子虚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-4dbaf1a5-195f-4924-845c-b61746bb3d3f","tags":[]},{"id":"poem-e486180d43a1ac38723bbbe0","title":"春日","author":"李咸用","dynasty":"唐","verses":["浩荡东风里，裴回无所亲。","危城三面水，古树一边春。","衰世难修道，花时不称贫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-ef6cc2fe-cf04-44b5-aa17-049709544d65","tags":[]},{"id":"poem-e49126f7e223d96921b24bf0","title":"春宿左省","author":"杜甫","dynasty":"唐","verses":["花隐掖垣暮，啾啾栖鸟过。","星临万户动，月傍九霄多。","不寝听金钥，因风想玉珂。","明朝有封事，数问夜如何。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-2769113d-0cac-4e67-83cb-0c10685f8381","tags":["唐诗三百首","爱国","写景","五言律诗"]},{"id":"poem-e49bf3b7f70055acb7a75d1f","title":"登楼值雨二首 一","author":"李咸用","dynasty":"唐","verses":["共讶高楼望，匡庐色已空。","白云横野阔，遮岳与天同。","数点雨入酒，满襟香在风。","远江吟得出，方下郡斋东。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-c9b97fac-69f5-4b09-af59-e59969077dc0","tags":["庐山"]},{"id":"poem-e4a5be9121b3da2a3faa7025","title":"木兰花・玉楼春·相离徒有相逢梦","author":"张先","dynasty":"宋","verses":["相离徒有相逢梦。","门外马蹄尘已动。","怨歌留待醉时听，远目不堪空际送。","今宵风月知谁共。","声咽琵琶槽上凤。","人生无物比多情，江水不深山不重。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-364","tags":[]},{"id":"poem-e4abe004f240cd5b81fdcd26","title":"次韵梁教章宰喜雪  其一","author":"陈造","dynasty":"宋","verses":["袖手飞雪前，徒有风雅渴。","久亲无言子，此兴今莫遏。","两君壮藻思，诗柄专杀活。","可须龙伯睡，骊珠乃平夺。","长翁久荒废，坐受儿女聒。","愁城正合围，醉乡况禁谒。","诗来起我敬，一嫡眇众孽。","此雪更此诗，清晤乃细阅。","晶荧盘走圆，便旋玉为屑。","汛扫无恶氛，肯綮有妙割。","解颐得匡鼎，和羹本商说。","技痒吐复吞，正恐诮燕说。","山城僧舍似，休务况佳节。","可疎触寒过，一笑卷蕉叶。","作诗供捧腹，巴唱酬白雪。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-f7cd6e06-5c23-468c-b936-e45cede55952","tags":[]},{"id":"poem-e4b59a263d4054b126a2adf4","title":"八归·秋江带雨","author":"史达祖","dynasty":"宋","verses":["秋江带雨，寒沙萦水，人瞰画阁愁独。","烟蓑散响惊诗思，还被乱鸥飞去，秀句难续。","冷眼尽归图画上，认隔岸、微茫云屋。","想半属、渔市樵村，欲暮竞然竹。","须信风流未老，凭持酒、慰此凄凉心目。","一鞭南陌，几篙官渡，赖有歌眉舒绿。","只匆匆眺远，早觉闲愁挂乔木。","应难奈，故人天际，望彻淮山，相思无雁足。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-184","tags":["宋词三百首"]},{"id":"poem-e4c6cd164bc483e4d95d33ee","title":"南乡子·渔市散","author":"李珣","dynasty":"五代","verses":["渔市散，渡船稀，越南云树望中微。","行客待湘天欲暮，送春浦，愁听猩猩啼瘴雨。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-32","tags":[]},{"id":"poem-e4c905cf0ed645e8fa6cd7ce","title":"临江仙·酥胸露出白皑皑","author":"邢俊臣","dynasty":"宋","verses":["酥胸露出白皑皑。","遥知不是雪，为有暗香来。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-842","tags":[]},{"id":"poem-e4c9f677da63905ed2cea17a","title":"东门之枌","author":"佚名","dynasty":"先秦","verses":["东门之枌，宛丘之栩。子仲之子，婆娑其下。","谷旦于差，南方之原。不绩其麻，市也婆娑。","谷旦于逝，越以鬷迈。视尔如荍，贻我握椒。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-136","tags":[]},{"id":"poem-e4cc7282101000b5d78a5e91","title":"古悠悠行","author":"李贺","dynasty":"唐","verses":["白景归西山，碧华上迢迢。","今古何处尽，千岁随风飘。","海沙变成石，鱼沫吹秦桥。","空光远流浪，铜柱从年消。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-82db064c-c110-44e1-a74f-c0bc0caa831a","tags":[]},{"id":"poem-e4ce4ae6e7f299ab52ef1772","title":"上小楼","author":"萧德祥《小孙屠》","dynasty":"元","verses":["公吏人排列两边，不由我心惊胆战。","怎推这铁锁沉枷，麻捶撒子？受尽熬煎。","假若使心似铁，这官法如炉烧炼。","休悲我枉屈后，死而无怨。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8641","tags":[]},{"id":"poem-e4d9e53ba41498ec81fcd31f","title":"春秋战国门 孙膑","author":"周昙","dynasty":"唐","verses":["曾嫌胜己害贤人，钻火明知速自焚。","断足尔能行不足，逢君谁肯不酬君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-82587e00-c82e-4a89-9dbf-d439034df2d3","tags":[]},{"id":"poem-e4dfa631305714c95538a32f","title":"赠皇甫侍御赴都（其二）","author":"元希声","dynasty":"唐","verses":["猗嗟众珍，以况君子。","公侯之胄，必复其始。","香器长材，温仪峻峙。","显此元明，于斯备矣。","（按此诗凡八首，已载《全唐诗》。","惟「其二」缺末两句，故依《珠英集》补全之。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-d4f5f7d8-629c-406e-b962-baf7efd628fb","tags":[]},{"id":"poem-e4e4934a23861c7a7989b695","title":"颂古十九首  其一二","author":"释法全","dynasty":"宋","verses":["钵里饭，桶里水，狗子咬人不露齿。","堪笑韶阳老古锥，倒地至今犹未起。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-e77c1f60-06ee-4b7d-ae91-b99bc6382d13","tags":[]},{"id":"poem-e4eec289515f1685219f6ebb","title":"西江月·欲了无生妙道","author":"张伯端","dynasty":"宋","verses":["欲了无生妙道，莫如自见真心。","真心无相亦无音。","清净法身只恁。","此道非无外有，非中亦莫求寻。","二边俱遣弃中心。","见了名为上品。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-993","tags":[]},{"id":"poem-e4fa208516de4e0772eef9d1","title":"酬杜使君见寄","author":"贯休","dynasty":"唐","verses":["轧轧复轧轧，更深门未关。","心疼无所得，诗债若为还。","露洒一鹤睡，钟余万象闲。","慙将此时意，明日寄东山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-13a138cd-8e8c-4334-9cc8-03c4149e2ad8","tags":[]},{"id":"poem-e4fbcfd106031109b348b67a","title":"皇帝癸未年膺运灭梁再兴（缺）迎太后七言诗","author":"李存勗","dynasty":"唐","verses":["禁烟节假赏幽闲，迎奉倾心乐贵颜。","䴏语雕梁声猗狔，鹦吟[绿]（渌）树韵开关。","为安家国千场战，思忆慈亲两鬓斑。","孝道未能全报得，直须顶戴遶弥山。","（〖1〗刘铭恕《斯坦因劫经录》云：「按《全唐文》一零四唐庄宗《亲至怀州奉迎太后敕》，略谓天下已定，理应到汾州亲迎太后，不得已只到怀州迎接，是知迎太后诗，即为此时作品。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-9345096d-69c8-49e5-b5d1-ffe85cb2be1d","tags":[]},{"id":"poem-e4fed68f0d4a39317a79a8bd","title":"河传·春浅","author":"纳兰性德","dynasty":"清","verses":["春浅，红怨，掩双环。","微雨花间，昼闲。","无言暗将红泪弹。","阑珊，香销轻梦还。","斜倚画屏思往事，皆不是，空作相思字。","记当时垂柳丝，花枝，满庭蝴蝶儿。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-213","tags":[]},{"id":"poem-e4ff23d02aca31d39aad59c5","title":"题时遁泽画卷十首  其四","author":"王柏","dynasty":"宋","verses":["礉礉石林立，滃滃云壑閟。","万杉最深中，莫有前朝寺。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-6b387495-c99b-4d66-846e-ede5fe5cba6b","tags":[]},{"id":"poem-e5028ccafa42700d03a3ec60","title":"长门怨","author":"崔道融","dynasty":"唐","verses":["长门春欲尽，明月照花枝。","买得相如赋，君恩不可移。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-db70d0ad-809e-4236-999d-7a773d0aaf46","tags":[]},{"id":"poem-e508d6aa971af57dacd51962","title":"享惠昭太子庙乐章","author":"孟简","dynasty":"唐","verses":["喧喧金石容既缺，肃肃羽驾就行列。","缑山遗响昔所闻，庙庭进旅今攸设。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-cc67ec48-0190-4d7b-8486-b1fca790b357","tags":[]},{"id":"poem-e50e6c61b9c289425b13b62a","title":"寻鸟窠迹","author":"魏璞","dynasty":"唐","verses":["（原注：唐道林禅师入秦望山，见长松蟠曲如盖，送栖止其上，故称鸟窠禅师。","）为访名僧迹，言寻小曲阿。","松林春日静，石迳晚云多。","道法传驯鹊，（原注：有鹊巢侧，自然驯狎。","）禅机显化螺。","（原注：尝入市，见食螺已截尾，乞放之池。","至今螺蛳繁生。）。","悉无尾如截，遗迹在芦院。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-3e3d34d3-16a4-4171-a722-ae8c7e3fb406","tags":[]},{"id":"poem-e512cad722da220b196d23a2","title":"秋夜","author":"佚名","dynasty":"唐","verses":["一夜秋声傍海多，五更寒色早来过。","自然覊旅肠堪断，况复猜嫌被网罗。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-49b3eb43-2c02-4a01-938a-f18dc752fe28","tags":[]},{"id":"poem-e515b087c19d0507b4253c11","title":"醉妆词","author":"后主衍","dynasty":"唐","verses":["者边走，那边走，只是寻花柳。","那边走，者边走，莫厌金杯酒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-f27f6d5d-9d1b-4e86-b88e-efd452c1d424","tags":[]},{"id":"poem-e52005f74832193347b87e57","title":"早春送湘潭李少府之任","author":"刘得仁","dynasty":"唐","verses":["柳新春水湄，春岸草离离。","祖席觞云尽，离人泪各垂。","业文传不朽，作尉岂多时。","公退琴堂上，风吹斑竹枝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-ddcfa724-864f-4ae0-ad50-9ae5fbc3b0f1","tags":[]},{"id":"poem-e52c77bb409888e7c292caa2","title":"送刘尊师祗诏阙庭三首 二","author":"曹唐","dynasty":"唐","verses":["五峰已别隔人间，双阙何年许再还。","既埽山川收地脉，须留日月驻天颜。","霞觞共饮身虽在，风驭难陪迹未闲。","从此枕中唯有梦，梦魂何处访三山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-f43b7380-4f3b-4b8f-ab2d-1fbfecad43b9","tags":[]},{"id":"poem-e53a421bf007ab181dfe3c84","title":"鹧鸪天·闲去街头赏大花","author":"陈造","dynasty":"宋","verses":["闲去街头赏大花。","翠帷珠幰护豪华。","西真宴罢群仙醉，千尺黄云错紫霞。","团粉黛，闹箫笳。","使星躔处住灵槎。","定知今夜游仙梦，不落西京姚魏家。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-416","tags":[]},{"id":"poem-e53d6213ba85f826ed3f6350","title":"题弹枭","author":"赵崇嶓","dynasty":"宋","verses":["弹枭莫弹鹤，惜此孤飞翰。","鹤举即千里，渺在青云端。","弹之固无益，瘦不充君盘。","却恐梧桐枝，无复栖凤鸾。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-1f31066d-00b4-445c-bc94-76e2cf880824","tags":[]},{"id":"poem-e54e2613cd6b2451d225834c","title":"送程给事知越州","author":"宋敏求","dynasty":"宋","verses":["浙东歌舞望旌麾，远泛樵风羽𬘫飞。","论譔内通仙殿籍，拜兴初别夕郎闱。","老人日俟刘公至，狂客今无贺监归。","闻有新诗频寄我，莫嗟梅雨裛朝衣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-ab42167c-ec48-4e7a-927d-f8c609ad51be","tags":[]},{"id":"poem-e5558d8734439bdb670ac6bc","title":"看花四绝句  其一","author":"司马光","dynasty":"宋","verses":["洛阳相望尽名园，墙外花胜墙里看。","手摘青梅共挼酒，何须一一具杯盘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-e96ded91-1497-43c5-af97-8e63330958ae","tags":[]},{"id":"poem-e559726c8b83a58a46dff3ac","title":"还自会稽歌","author":"李贺","dynasty":"唐","verses":["野粉椒壁黄，湿萤满梁殿。","台城应教人，秋衾梦铜辇。","吴霜点归鬓，身与塘蒲晚。","脉脉辞金鱼，羁臣守迍贱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-eb9c11f4-96b8-4445-9ca8-7a6f7c87da21","tags":[]},{"id":"poem-e55b406210e77916b31d22a5","title":"洞庭湖","author":"曹松","dynasty":"唐","verses":["东西南北各连空，波上唯留小朵峰。","长与岳阳翻鼓角，不离云梦转鱼龙。","吸廻日月过千顷，铺尽星河剩一重。","直到劫余还作陆，是时应有羽人逢。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-52aacc69-47b6-499a-94a5-3b66eed1b276","tags":["洞庭湖"]},{"id":"poem-e562b904912e09ef09c5a0eb","title":"仙源即事三首  其一","author":"王镃","dynasty":"宋","verses":["鼎沸秦汤满世间，恨无凉雨洗松关。","道人识破先天易，又欲携包过别山。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-3ebc312f-137d-4913-9a09-9d80756f5fd4","tags":[]},{"id":"poem-e565cb7420d71ff49e656dfb","title":"贺圣朝·满斟绿醑留君住","author":"叶清臣","dynasty":"宋","verses":["满斟绿醑留君住。","莫匆匆归去。","三分春色二分愁，更一分风雨。","花开花谢、都来几许。","且高歌休诉。","不知来岁牡丹时，再相逢何处。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-594","tags":[]},{"id":"poem-e566199a786854737076a41f","title":"回中夜访独孤从事","author":"刘得仁","dynasty":"唐","verses":["满庭霜月魄，风静绝纤闻。","边境时无事，州城夜访君。","拥裘听塞角，酌醴话湘云。","赞佐元戎美，恩齐十万军。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-3d828921-91fb-4ada-8631-dfae14941a9b","tags":[]},{"id":"poem-e56aa32fe3fbf09e80a5324f","title":"五更转","author":"刘唐卿《白兔记》","dynasty":"元","verses":["恨命乖遭折挫，爹娘知苦么？哥哥嫂嫂你好横心做，赶出刘郎，罚奴挨磨。","叫天不应，地不闻，如何过？(合)奴家那曾，那曾识挨磨、挑水辛勤，只为刘大。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8917","tags":[]},{"id":"poem-e56d039f9005ffdc1630e6c7","title":"享太庙乐章","author":"刘晏","dynasty":"唐","verses":["汉祚惟永，神功中兴。","夙驱氛祲，天覆黎蒸。","三光再朗，庶绩其凝。","重熙累叶，景命是膺。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-102198f6-fc4f-4183-8e98-85df362362bb","tags":[]},{"id":"poem-e57048d1ac20a894459f710a","title":"鼓吹曲辞 巫山高二首 二","author":"沈佺期","dynasty":"唐","verses":["神女向高唐，巫山下夕阳。","裴回作行雨，婉娈逐荆王。","电影江前落，雷声峡外长。","霁云无处所，台馆晓苍苍。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-37063ab6-a303-4864-b68d-9888d19a5124","tags":[]},{"id":"poem-e571b055f78771803c31ed02","title":"拜中岳命作  其一","author":"米芾","dynasty":"宋","verses":["云水心常结，风尘面久卢。","重寻钓鼇客，初入选仙图。","鼠雀真官耗，龙蛇与众俱。","却怀闲禄厚，不敢著潜夫。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-e84aaeb8-a526-476a-8884-09766e402dc1","tags":[]},{"id":"poem-e57412302dd7931f2bc6001f","title":"春望","author":"杜甫","dynasty":"唐","verses":["国破山河在，城春草木深。","感时花溅泪，恨别鸟惊心。","烽火连三月，家书抵万金。","白头搔更短，浑欲不胜簪。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-e9e6425c-6c14-4f69-8694-87a8b96a43de","tags":["唐诗三百首","战争","忧国忧民","爱国","五言律诗","初中古诗","八年级上册(课内)","思乡","写鸟","鸟"]},{"id":"poem-e57a0b343a8503d62d172391","title":"江南逢李龟年","author":"杜甫","dynasty":"唐","verses":["歧王宅里寻常见，崔九堂前几度闻。","正是江南好风景，落花时节又逢君。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-ae5b1a15-0b5c-4578-8f31-1b60030633a4","tags":["唐诗三百首","初中古诗","七言绝句","怀念","感伤","七年级下册(课外)"]},{"id":"poem-e57bc1b0f338d82adcb5ac03","title":"偈颂 八","author":"文偃","dynasty":"唐","verses":["万像森罗极细微，素话当人却道非。","相逢相见呵呵笑，顾伫停机复是谁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-37a6b395-98c2-44e5-adea-f5a0325dc24b","tags":[]},{"id":"poem-e57c755643ac6489e6ccb246","title":"蝶恋花·眼底风光留不住","author":"纳兰性德","dynasty":"清","verses":["眼底风光留不住，和暖和香，又上雕鞍去。","欲倩烟丝遮别路，垂杨那是相思树。","惆怅玉颜成间阻，何事东风，不作繁华主。","断带依然留乞句，斑骓一系无寻处。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-125","tags":[]},{"id":"poem-e5806da7360fdfec9f7ea35a","title":"郊庙歌辞 后唐宗庙乐舞辞 昭德舞","author":"崔居俭、卢文纪","dynasty":"唐","verses":["懿彼明德，赫赫煌煌。","名高阃域，功著旗常。","道符休泰，运叶祺祥。","庆传万祀，以播耿光。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-3efeffba-63c5-4de4-90d4-203e176ea4b6","tags":[]},{"id":"poem-e598032a2378f0de8c9c4823","title":"醉高楼·浮云散","author":"张镃","dynasty":"宋","verses":["浮云散，天似碧琉璃。","月正是、上弦时。","姮娥蟾兔俱何在，广寒宫殿不应亏。","这神功，千万世，有谁知。","甚知解、催人须鬓老。","更不算、将人情绪恼。","撺掇酒，撼摇诗。","山头望伴疏星落，庭前看照好花移。","夜无眠，应笑我，怎如痴。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-355","tags":[]},{"id":"poem-e59f58cab3481bb98caf7cd9","title":"柳叶儿","author":"杨景贤","dynasty":"元","verses":["我又想当年时分，哭啼啼送你到江滨。","今日个蒲帆百尺西风顺，休辞困，暂劳神，天那，谁承望血修书弄假成真？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-7966","tags":[]},{"id":"poem-e5a546d5cd629d6baca22ad4","title":"采桑子·彤霞久绝飞琼字","author":"纳兰性德","dynasty":"清","verses":["彤霞久绝飞琼字，人在谁边。","人在谁边，今夜玉清眠不眠。","香销被冷残灯灭，静数秋天。","静数秋天，又误心期到下弦。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-31","tags":[]},{"id":"poem-e5a7a6830832f9700112ddc2","title":"十玄谈（幷序） 乡还曲（《大正》本、《偈颂》作「达本」）","author":"常察","dynasty":"唐","verses":["勿于中路事空王，策杖咸须归（《大正》本、《偈颂》作「还须达」）本乡。","云水隔时君莫住，雪山深处我非忙（《大正》本、《偈颂》作「忘」）。","寻思去日颜如玉，嗟叹回来（《偈颂》作「时」）鬓似霜。","撒手到家人不识，更无一物献尊堂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-5fedcff1-aeb4-4f53-b69f-4c6b668bf159","tags":[]},{"id":"poem-e5ad9a5a3d89d0229098d74e","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(净丑上)雪落纷纷似银铺，万里江山如画图。","鹭鸶失队难寻觅，黑和尚变化白师姑。","刘健儿，怎么不买冻鱼酒来我每吃？(生)不曾支粮，支了粮请你每一醉。","(净丑)也罢。","刘健儿，今晚巡更，该你巡夜。","一更是我，二更是他。","三更四更五更都是你。","老爷有铜牌花号为准，交你更次提铃喝号。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8904","tags":[]},{"id":"poem-e5b28d72ace324118379b9b0","title":"湘弦曲","author":"庄南杰","dynasty":"唐","verses":["楚云铮铮戛秋露，巫云峡雨飞朝暮。","古磬高敲百尺楼，孤猨夜哭千丈树。","云轩碾火声珑珑，连山卷尽长江空。","莺啼寂寞花枝雨，鬼啸荒郊松柏风。","满堂怨咽悲相续，苦调中含古离曲。","繁弦响绝楚魂遥，湘江水碧湘山绿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-9cb64625-be19-4118-bc44-bafaf721b140","tags":["长江"]},{"id":"poem-e5b371e256dda95b5d058d65","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["从别后痛哀戚，况家中音信稀。","为公姑多怨忆，为爹行又长垂泪。","本见公姑无愧色，又得与爹行相倚依。","(合前)(末净丑唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5282","tags":[]},{"id":"poem-e5b8b9d8ee57fac40c12e6e6","title":"六五","author":"王梵志","dynasty":"唐","verses":["立身存笃信，（「存」，斯三三九三卷作「在」。","）景行胜将金。","在处人携接，谙知无负心。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-270c57f8-3512-4dbb-b5fa-2d0ab86b9289","tags":[]},{"id":"poem-e5c09f5ce757d4750cc63740","title":"倒犯·尽日、任梧桐自飞","author":"方千里","dynasty":"宋","verses":["尽日、任梧桐自飞，翠阶慵扫。","闲云散缟。","秋容莹、暮天清窈。","斜阳到地，楼阁参差帘栊悄。","嫩袖舞凉飔，拂拂生林表。","荡尘襟，写名醥。","携手故国，胜事寻踪，松篁幽径窎。","曲沼瞰静绿，荫檐影、龟鱼小。","信倦迹、归来好。","倩叮咛、长安游子道。","任鬓发霜侵，莫待菱花照。","醉乡深处老。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-551","tags":[]},{"id":"poem-e5c2eabcf69ffb1712fe9ea9","title":"行田诗","author":"张又新","dynasty":"唐","verses":["白石岩前湖水春，湖边旧境有清尘。","欲追谢守行田意，今古同忧是长人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-8583618a-0931-4733-8945-75b761e34ff1","tags":[]},{"id":"poem-e5d27b473cc5644b92dcbab1","title":"和僧啸云双插法藏寺韵","author":"柴元彪","dynasty":"宋","verses":["我来扣角二峰前，此寺因知五百年。","草木尚涵唐雨露，钟鱼犹镇宋山川。","世情苍狗浮云外，客思孤鸿落日边。","闲拂旧题追往事，我须僧发两皤然。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-f2b8f96c-8ac0-444a-920d-50db8a3505f2","tags":[]},{"id":"poem-e5d7130027624d17ad3fec34","title":"再用才子富文华校雠天禄阁韵赠周教授  其一","author":"陈造","dynasty":"宋","verses":["仙人藤阴梦，金骨窖黄埃。","当年晁张双，缩手推其才。","陈编且千载，万蛰听春雷。","偕公闲吊古，文游但荒台。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-a5164555-b734-49ce-b9da-ed77790016ca","tags":[]},{"id":"poem-e5ece1839c70d2033fa28d55","title":"边上行","author":"贯休","dynasty":"唐","verses":["黑松林外路，风角远嗈嗈。","朔气生荒堡，秋尘满病容。","豺掊沙底骨，人上月边烽。","休作西行计，西行地渐凶。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-525e545e-5080-4ec2-8ea9-123c757d3df7","tags":[]},{"id":"poem-e5f22efdac0fc7a29a7279c1","title":"郊庙歌辞 周宗庙乐舞辞 善庆舞","author":"不详","dynasty":"唐","verses":["卜世长，帝祚昌。","定中国，服四方。","修明祀，从旧章。","奏激楚，转清商。","罗俎豆，列簪裳。","歌累累，容皇皇。","望来格，降休祥。","祝敢告，寿无疆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-f8e557fd-6b68-47b3-b14f-b26de587fe6b","tags":[]},{"id":"poem-e5fa5c8d9ab1e62d1e2a4ba7","title":"九日陪越州元相燕龟山寺","author":"赵嘏","dynasty":"唐","verses":["佳晨何处泛花游，丞相筵开水上头。","双影斾摇山雨霁，一声歌动寺云秋。","林光静带高城晚，湖色寒分半槛流。","共贺万家逢此节，可怜风物似荆州。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-d654208b-ae8d-4b62-8c21-d2b81192685f","tags":[]},{"id":"poem-e5fbb0f0ad0b3d4743560bf8","title":"句 一","author":"沈彬","dynasty":"唐","verses":["花片乱飞愁杀人。","（《永乐大典》卷八二二引《考古质疑》引葛次仲集句引。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-cb6e057e-9cba-43e7-b8e1-f7633442de22","tags":[]},{"id":"poem-e5fbf9d2c13e064a67b1b299","title":"青㠗山","author":"张又新","dynasty":"唐","verses":["灵海泓澄匝翠峰，昔贤心赏已成空。","今朝亭馆无遗制，积水沧浪一望中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-852372d6-64ff-4341-816b-63e86e8d2e25","tags":[]},{"id":"poem-e5fce51faa7c92bca1501b1b","title":"祝英台","author":"徐田臣《杀狗记》","dynasty":"元","verses":["草芊芊，花苒苒，轻暖艳阳天。","才子艳质，簇拥名园，嬉戏笑蹙秋千。","排筵，好向花柳亭前，寻芳消遣。","(合)我和你双双游赏欢宴。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1737","tags":[]},{"id":"poem-e5fdb96a4df42b86a1745784","title":"点绛唇·秩秩宾筵","author":"张孝祥","dynasty":"宋","verses":["秩秩宾筵，玉潭春涨玻璃满。","旆霞风卷。","可但长安远。","夏木成阴，路袅薰风转。","空留恋。","细吹银管。","别意随声缓。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-385","tags":[]},{"id":"poem-e6050c17bdf8eee82b22e4cb","title":"和邢端公登台春望句句有春字之什","author":"皎然","dynasty":"唐","verses":["春日绣衣轻，春台别有情。","春烟间草色，春鸟隔花声。","春树乱无次，春山遥得名。","春风正飘荡，春瓮莫须倾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-588a3bdb-03ab-45c2-89df-2aef3ec414a6","tags":[]},{"id":"poem-e60ad9b6d04863bfab6df249","title":"玉泉十二韵","author":"纳兰性德","dynasty":"清","verses":["地涌西山脉，名标禁御泉。","百层飞作雨，万顷汇成渊。","润下终归海，源高却自天。","萦烟来树杪，带雪落云边。","隐见瑶光曳，琤苁佩响传。","红栋桥宛转，乌榜棹洄沿。","蛟龙蟠翠岛，雁鹜起琼田。","镜面晶荧合，珠痕荡漾圆。","翠流初放荇，娇拥半开莲。","睿赏悬孤鉴，馀波溢九璇。","那居真有庆，鱼藻在诗篇。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-233","tags":[]},{"id":"poem-e60e061e8b4529892bd0832f","title":"煎茶峰","author":"陈岩","dynasty":"宋","verses":["缓火烘来活水煎，山头卓锡取清泉。","品茶嬾检茶经看，舌本无非有味禅。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-c2621627-b0e7-463d-a4be-ff0c1e0f7223","tags":[]},{"id":"poem-e6202509bc147ed6d6ea6b9f","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(小生)一碗家常饭，何须苦挂牵？略且止饥寒。","有日春雷动，管取朝帝辇。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8797","tags":[]},{"id":"poem-e6217b78b86412f69df849de","title":"寄邓洵美","author":"王溥","dynasty":"唐","verses":["衡阳归鴈别重湖，衘到同人一纸书。","忽见姓名双泪落，不知消息十年余。","彩衣我已登黄合，白社君犹葺旧居。","南望荆门千里外，暮云重叠满晴虚。","（见前书同卷引《雅言系述》。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-5a68eb22-a928-4310-90d3-96f0393dbbf6","tags":[]},{"id":"poem-e627b59b70099f69224a6584","title":"杜鹃行","author":"杜甫","dynasty":"唐","verses":["君不见昔日蜀天子，化作杜鹃似老乌。","寄巢生子不自啄，群鸟至今与哺雏。","虽同君臣有旧礼，骨肉满眼身羁孤。","业工窜伏深树里，四月五月偏号呼。","其声哀痛口流血，所诉何事常区区。","尔岂摧残始发愤，羞带羽翮伤形愚。","苍天变化谁料得，万事反复何所无。","万事反复何所无，岂忆当殿群臣趋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-91233d92-0156-4ead-9981-a5b834f9a3d2","tags":["感慨","悲痛","写鸟","惋惜","鸟"]},{"id":"poem-e62e00c6e241307e9dd3eb0c","title":"山寺看樱桃花题僧壁","author":"刘言史","dynasty":"唐","verses":["楚寺春风腊尽时，含桃先坼一千枝。","老僧不语傍边坐，花发人来总不知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-cc422ff1-f5be-4c3d-8875-10671e9cad85","tags":[]},{"id":"poem-e6392741db5a043836eaccb9","title":"惠山归晚辞县斋小集","author":"释居简","dynasty":"宋","verses":["癯冰瘠雪凝霜澌，冻涩苔痕老更奇。","旅雁退飞寒力劲，水边云冷出山迟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-916c7a07-b845-4445-9fc1-303bfff0b7a6","tags":[]},{"id":"poem-e63a193fab07143fbbfac3f3","title":"安公子·弱柳丝千缕","author":"袁去华","dynasty":"宋","verses":["弱柳丝千缕。","嫩黄匀遍鸦啼处。","寒入罗衣春尚浅，过一番风雨。","问燕子来时，绿水桥边路。","曾画楼、见个人人否。","料静掩云窗，尘满哀弦危柱。","庾信愁如许。","为谁都著眉端聚。","独立东风弹泪眼，寄烟波东去。","念永昼春闲，人倦如何度。","闲傍枕、百啭黄鹂语。","唤觉来厌厌，残照依然花坞。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-12","tags":["宋词三百首"]},{"id":"poem-e645c43419d9449bb77bbea8","title":"哭补阙亡友綦毋学士","author":"王湾","dynasty":"唐","verses":["明代资多士，儒林得异才。","书从金殿出，人向玉墀来。","词学张平子，风仪褚彦回。","崇仪希上德，近侍接元台。","曩契心期早，今游宴赏陪。","屡迁君擢桂，分尉我从梅。","忽遇乘轺客，云倾构厦材。","泣为洹水化，叹作泰山颓。","冀善初将慰，寻言半始猜。","位联情易感，交密痛难裁。","远日寒旌暗，长风古挽哀。","寰中无旧业，行处有新苔。","反哭魂犹寄，终丧子尚孩。","葬田门吏给，坟木路人栽。","遽泄悲成往，俄传宠令回。","玄经贻石室，朱绂耀泉台。","地古春长闭，天明夜不开。","登山一临哭，挥泪满蒿莱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-e88124ec-8947-407d-a166-3888dc12d228","tags":["泰山"]},{"id":"poem-e655f83fa2a13ca4bea58d8b","title":"送友人使夷陵","author":"崔翘","dynasty":"唐","verses":["猨鸣三峡里，行客旧沾裳。","复道从兹去，思君不暂忘。","开襟春叶短，分手夏条长。","独有幽庭桂，年年空自芳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-72c5f082-92d4-4edf-9578-6b0d9188f80c","tags":[]},{"id":"poem-e65b848814b3a0c5947cbecf","title":"望江南・忆江南·毛发落","author":"陈朴","dynasty":"宋","verses":["毛发落，丹左运行阳。","胎色渐红阴渐小，推移岁运助干刚。","育火养中央。","成物象，五岳辨微茫。","出入尚迟形尚小，晨昏天籁奏笙簧。","常饮玉壶浆。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-962","tags":[]},{"id":"poem-e667003d64c5c1b8120e5767","title":"和张仆射塞下曲 三","author":"卢纶","dynasty":"唐","verses":["月黑鴈飞高，单于夜遁逃。","欲将轻骑逐，大雪满弓刀。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-ee2a3000-9127-43fa-8618-89a1937322cb","tags":["战争","冬天","将军","唐诗三百首","乐府","边塞","赞美"]},{"id":"poem-e66e011452ed25d28226de52","title":"木兰花·独上小楼春欲暮","author":"韦庄","dynasty":"五代","verses":["独上小楼春欲暮，愁望玉关芳草路。","消息断，不逢人，欲敛细眉归绣户。","坐看落花空叹息，罗袂湿斑红泪滴。","千山万水不曾行，魂梦欲教何处觅。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-24","tags":[]},{"id":"poem-e6709efa55ebf5f00f13b664","title":"省题诗二十一首 文不加点","author":"王棨","dynasty":"唐","verses":["娱宾初命赋，摛翰已堪夸。","思发才无滞，文成点不加。","笔端舒锦绣，手下走龙蛇。","罢益银钩势，休添丽泽华。","误蝇宁复见，倚马未为嘉。","有愧当明试，含毫到日斜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-8cbf2238-b598-482c-a83d-a6189e26622c","tags":[]},{"id":"poem-e672a060f2709cf816a55e3d","title":"秦淮","author":"华镇","dynasty":"宋","verses":["渺渺方山道，江流一派通。","寒沙翘白鹭，夕霭暝丹枫。","平截埋金地，虚涵建邺宫。","六朝乘王气，疏凿竟无功。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-8fcc7a5f-0755-4e90-a413-7ccc2adf64a1","tags":[]},{"id":"poem-e683814263d559af4be27f99","title":"吕元直得书天台郭外治园林作退老堂求诗为赋两章  其二","author":"李纲","dynasty":"宋","verses":["周遭叠嶂俯清流，卜筑园林事事幽。","春日莺花随衮绣，秋来松菊照林丘。","谢公终为苍生起，裴相聊成绿野谋。","圣主思贤方仄席，未应长伴赤松游。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-3a2696b2-6361-4671-978a-bc3c097ee0d3","tags":[]},{"id":"poem-e68bfdb2aa0fb1f103a4a072","title":"李员外秦援宅观妓","author":"沈佺期","dynasty":"唐","verses":["盈盈粉署郎，五日宴春光。","选客虚前馆，徵声徧后堂。","玉钗翠羽饰，罗袖郁金香。","拂黛随时广，挑鬟出意长。","啭歌遥合态，度舞暗成行。","巧落梅庭里，斜光暎晓妆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-dbce5180-34f2-4d50-9a36-9db07635d349","tags":[]},{"id":"poem-e694130fc540e5bda6f29ecf","title":"采苓","author":"佚名","dynasty":"先秦","verses":["采苓采苓，首阳之巅。人之为言，苟亦无信。舍旃舍旃，苟亦无然。人之为言，胡得焉？","采苦采苦，首阳之下。人之为言，苟亦无与。舍旃舍旃，苟亦无然。人之为言，胡得焉？","采葑采葑，首阳之东。人之为言，苟亦无从。舍旃舍旃，苟亦无然。人之为言，胡得焉？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-124","tags":[]},{"id":"poem-e69a8f38d859173a078a271f","title":"腊梅花","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["我孩儿出去在今日中，爹爹妈妈来相送。","但愿得鱼化龙，青云得路，桂枝高折步蟾宫。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4946","tags":[]},{"id":"poem-e69be8ba8b88e1f7f03b119b","title":"游仙词三十三首  其三三","author":"王镃","dynasty":"宋","verses":["月娥树上赤花香，羽帐琼楼子夜长。","玉兔白蛙身不老，水银一臼结玄霜。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-37021886-54c8-4238-8507-7522d9c40df8","tags":[]},{"id":"poem-e6aa26f6ec03c6c64e552071","title":"浣溪沙·共饮昏昏到暮鸦","author":"吕本中","dynasty":"宋","verses":["共饮昏昏到暮鸦。","不须春日念京华。","迩来沈醉是生涯。","不是对君犹惜醉，只嫌春病却怜他。","愿为蜂采落残花。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-736","tags":[]},{"id":"poem-e6b7e4e7f8c1b2ce64a39eed","title":"偈 四","author":"契此","dynasty":"唐","verses":["吾有一躯佛，世人皆不识。","不塑亦不装，不雕亦不刻。","无一滴灰泥（《布袋和尚传》作「无一块泥土」），无一点彩色。","人画画不成。","贼偷偷不得。","体相本自然，清净非拂拭（《布袋和尚传》作「常皎洁」）。","虽然是一躯，分身千百亿。","（以上四首均见《五灯会元》卷二、《明州定应大师布袋和尚传》、《明州岳林寺志》〖清戴明琮撰〗卷三。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-be2116fb-2e63-409d-bfe6-0b9cfe908e65","tags":[]},{"id":"poem-e6c08df9baefc8280d0463b2","title":"题友人诗集","author":"王镃","dynasty":"宋","verses":["学诗玄妙似参禅，又似凡人去学仙。","吟得悟时皮骨换，一天风露响灵蝉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-1fff3ca9-4a6f-475f-961f-9f47ef54ec7a","tags":[]},{"id":"poem-e6c1e1642be3abe08b841f3e","title":"和梁签判颍州西湖十三题 飞盖桥","author":"苏颂","dynasty":"宋","verses":["朱桥矗矗两园间，湖水平时柳可攀。","车马等闲湖上去，游人常踏月中还。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-5829b919-33bb-4d82-96e6-1b2727093be2","tags":["西湖"]},{"id":"poem-e6c530332fb4d100a2590c07","title":"鹧鸪天·昼得游嬉夜得眠","author":"张孝祥","dynasty":"宋","verses":["昼得游嬉夜得眠。","农桑欲遍楚山川。","问看百姓知公否，馀子纷纷定不然。","思主眷，酌民言。","与民称寿拜公前。","只将心与天通处，合住人间五百年。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-239","tags":[]},{"id":"poem-e6d32292a09d1b29aaa46f7c","title":"泛溪","author":"项斯","dynasty":"唐","verses":["溪船泛渺弥，渐觉灭炎辉。","动水花连影，逢人鸟背飞。","深犹见白石，凉好换生衣。","未得多诗句，终须隔宿归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-55c6730d-21b4-4081-94ce-4db0ed748fa0","tags":[]},{"id":"poem-e6d8eb4a21a1fba0f4ff1efd","title":"从崇山向越常","author":"沈佺期","dynasty":"唐","verses":["朝发崇山下，暮坐越常阴。","西从杉谷度，北上竹溪深。","竹溪道明水，杉谷古崇岑。","差池将不合，缭绕复相寻。","桂叶藏金屿，藤花闭石林。","天窗虚的的，云窦下沈沈。","造化功偏厚，真仙迹每临。","岂徒探怪异，聊欲缓归心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-c577ccc9-300b-4231-a774-ef6d4f615558","tags":[]},{"id":"poem-e6daad71c6918bee6bee07e0","title":"观《山海图》二首 其一","author":"张祜","dynasty":"唐","verses":["古色辨微茫，华夷在一堂。","云霞开藻井，天地出雕梁。","细草生毫末，轻风拂黛光。","夜山犹带景，秋树不凋霜。","隐竹才分翠，秾华欲堕香。","无风帆自起，度日鸟空翔。","舟势鲸吞久，楼形蜃吐长。","更看台上镜，造化落中央。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-886e5d0d-ae10-431e-adf8-d66636854b43","tags":[]},{"id":"poem-e6daf6eb133ca7f9953fc004","title":"别于鹄","author":"张籍","dynasty":"唐","verses":["离灯及晨辉，行人起复思。","出门两相顾，青山路逶迤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-9c703f78-d424-4982-b5d0-fcc5c5b219f5","tags":[]},{"id":"poem-e6dca45543814a236a1c786d","title":"春日望海","author":"太宗皇帝","dynasty":"唐","verses":["披襟眺沧海，凭轼玩春芳。","积流横地纪，疎派引天潢。","仙气凝三岭，和风扇八荒。","拂潮云布色，穿浪日舒光。","照岸花分彩，迷云雁断行。","怀卑运深广，持满守灵长。","有形非易测，无源讵可量。","洪涛经变野，翠岛屡成桑。","之罘思汉帝，碣石想秦皇。","霓裳非本意，端拱且图王。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-fdf597bd-d45c-407d-9a5b-739be83771de","tags":[]},{"id":"poem-e6f70420c2d4dcf09dd29cda","title":"长安秋望","author":"赵嘏","dynasty":"唐","verses":["云物凄凉拂署流，汉家宫阙动高秋。","残星几点雁横塞，长笛一声人倚楼。","紫艳半开篱菊静，红衣落尽渚莲愁。","鲈鱼正美不归去，空戴南冠学楚囚。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-長安秋望","tags":[]},{"id":"poem-e6f84c7120d94a8574347edc","title":"曲玉管·陇首云飞","author":"柳永","dynasty":"宋","verses":["陇首云飞，江边日晚，烟波满目凭阑久。","立望关河萧索，千里清秋。","忍凝眸。","杳杳神京，盈盈仙子，别来锦字终难偶。","断雁无凭，冉冉飞下汀洲。","思悠悠。","暗想当初，有多少、幽欢佳会，岂知聚散难期，翻成雨恨云愁。","阻追游。","每登山临水，惹起平生心事，一场消黯，永日无言，却下层楼。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-141","tags":["宋词三百首"]},{"id":"poem-e6f9006b493bba6e301b5a9d","title":"上灵州令狐相公","author":"李洞","dynasty":"唐","verses":["征蛮破虏汉功臣，提劒归来万里身。","笑倚凌烟金柱看，形容憔悴老于真。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-f0555091-c336-42f6-98e6-8b5103b2a298","tags":[]},{"id":"poem-e7171edfffaebe3e83b195e4","title":"喜朝天・踏莎行·晓云开","author":"张先","dynasty":"宋","verses":["晓云开。","睨仙馆陵虚，步入蓬莱。","玉宇琼甃，对青林近，归鸟徘徊。","风月顿消清暑，野色对、江山助诗才。","潇鼓宴，璇题宝字，浮动持杯。","人多送目天际，识渡舟帆小，时见潮回。","故国千里，共十万室，日日春台。","睢社朝京非远，正和羹、民口渴盐梅。","佳景在，吴侬还望，分阃重来。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-332","tags":[]},{"id":"poem-e71c29d60297095baa110292","title":"送僧入马头山","author":"贯休","dynasty":"唐","verses":["马头宝峰，秀塞寒空。","有叟有叟，真隐其中。","无味醍醐，亦非般若。","白趾碧目，数百潇洒。","苦竹大于杉，白熊卧如马。","金钟撼壑，布水喷瓦。","芙蓉堂开峰月入，岳精踏雪立屋下。","伊余解攀缘，已是非常者。","更有叟，独往来，与我语。","情无刚彊，气透今古。","竹笠援补，芒鞋藤乳。","北风倒人，干雪不聚。","满头霜雪汤雪去，汤雪去。","无人及，空望真气江上立。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-6fad8b1f-159f-4826-b7c2-14d4cb7b37e9","tags":[]},{"id":"poem-e71e5d093b841bb2d472348d","title":"登天都峰","author":"缪岛云","dynasty":"唐","verses":["盘空千万仞，险若上丹梯。","迥入天都里，回看鸟道低。","他山青点点，远水白凄凄。","欲下前峰暝，岩间宿锦鸡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-02fc2f92-eb29-46cd-be7b-f57d14ab1fa1","tags":[]},{"id":"poem-e72c2adaa1b630f054b70d52","title":"沉机石","author":"陈岩","dynasty":"宋","verses":["忠诚为国心无累，简易临民讼自稀。","与世相安真省事，若为作意苦沉机。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-0454ca7a-8b8f-4719-9d65-eaa48c1bd68f","tags":[]},{"id":"poem-e72dc7cbcf90b08293f64064","title":"挽丁知县","author":"王柏","dynasty":"宋","verses":["蚤识北平贵，从游五十年。","迟迟登虎榜，急急到凫仙。","振起非无地，荣枯自有天。","老成雕落尽，一壑锁苍烟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-1f2c2c95-0497-4ab2-b1b7-5fd5b9098e2d","tags":[]},{"id":"poem-e72ef9ecfcff9b17e311aae5","title":"酬元主簿子球别赠","author":"皎然","dynasty":"唐","verses":["故人方远适，访我陈别情。","此夜偶禅室，一言了无生。","览君缄中宝，如搴清玉瑛。","胡为蕴高价，岁晚徒营营。","辞秩贫且病，何人见艰贞。","出无黄金橐，空歌白苎行。","威迟策驽马，独望故关树。","渺渺千里心，春风起中路。","近闻新拜命，鸾凤犹栖棘。","劝君寄一枝，且养冥冥翼。","甘泉多竹花，明年待君食。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-8161a068-be19-4104-a253-41c822f3774b","tags":[]},{"id":"poem-e738c5482d8975e86c9bc751","title":"送刘羲仲检讨","author":"林敏修","dynasty":"宋","verses":["二年食贫儿女煎，大寒客居衣里穿。","闭门穷巷气不屈，谁问过午无炊烟。","腹中万卷自得饱，冷热不假世人怜。","思归一日止旧隠，墙垣荆棘荒三椽。","青山不肯埋妙器，幅巾却作康庐仙。","今年再渡江北船，旋买走马趋日边。","即今日月九天上，陛下旰食思求贤。","结交老苍半台阁，亨衢插翼看翩翩。","朱颜谁无起家念，壮志输君先著鞭。","我今憔悴类蟠木，斧斤不到终天年。","病身无用聊自惜，对榻犹堪雨夜眠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-27770ffc-aa47-4fe0-bcfd-600a10a757ce","tags":[]},{"id":"poem-e7571fbf1bfb6861f5788625","title":"述怀一首","author":"杜甫","dynasty":"唐","verses":["去年潼关破，妻子隔绝久。","今夏草木长，脱身得西走。","麻鞋见天子，衣袖露两肘。","朝廷慜生还，亲故伤老丑。","涕泪授拾遗，流离主恩厚。","柴门虽得去，未忍即开口。","寄书问三川，不知家在否。","比闻同罹祸，杀戮到鸡狗。","山中漏茅屋，谁复依户牖。","摧颓苍松根，地冷骨未朽。","几人全性命，尽室岂相偶。","嵚岑猛虎场，郁结回我首。","自寄一封书，今已十月后。","反畏消息来，寸心亦何有。","汉运初中兴，生平老耽酒。","沈思欢会处，恐作穷独叟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-e0ec8fe8-3c0a-4b2e-85b7-30fe8f267fe4","tags":[]},{"id":"poem-e75cf19d69521cff433ee018","title":"·","author":"段义宗","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-d826e40d-7ca7-443e-8d3e-1afb61a0e471","tags":[]},{"id":"poem-e76401dc80391eb08e7bb32c","title":"次衡州二首  其二","author":"李纲","dynasty":"宋","verses":["弄兵赤子满潢池，渤海龚生真吏师。","欲使循良买牛犊，会须哀痛问疮痍。","东南王气虽方振，西北流民自可悲。","七万虎狼皆敛戢，庙堂还有阿谁知。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-9a1ffc01-7c70-41c6-ba75-30dd6015d8de","tags":[]},{"id":"poem-e768dadd6845728a77bced3c","title":"刘衮","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["乘驿骑，乘驿骑，陈留去开旨。","(净丑上唱)略请行轩，到此少住。","(外)唯，此间是何处？住此还怎地？(净丑)此间站里，待将鞍马来换取。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5269","tags":[]},{"id":"poem-e77253633e5e410199727490","title":"寓居临平山下三首 其二","author":"张祜","dynasty":"唐","verses":["一角横查碍小滩，渔舟稍稍避回湍。","鹿蹄踏叶暮山响，龟壳曝沙春水寒。","诗句近吟知律变，《易》书穷讨觉才难。","风光好处自擕酌，归去醉扶花药栏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-8150ee7e-61e3-4b9b-82b5-6b46385af482","tags":[]},{"id":"poem-e772e8c251578ef8df68bc22","title":"赋残雪","author":"释干康","dynasty":"宋","verses":["六出奇花已住开，郡城相次见楼台。","时人莫把和泥看，一片飞从天上来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-5deea0c7-645b-4858-a13d-c56bdfbe7ae3","tags":[]},{"id":"poem-e775131266b9b8853e2df0e6","title":"兵后送薛居士移家安吉","author":"皎然","dynasty":"唐","verses":["旧游经丧乱，道在复何人。","寒草心易折，闲云性常真。","交情别后见，诗句比来新。","向我桃州住，惜君东岭春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-786d2b48-9685-4b38-8d5d-01d29ad520ad","tags":[]},{"id":"poem-e77d1f9de4b1164d2e28aa51","title":"失调名·瑞脑烟残","author":"李清照","dynasty":"宋","verses":["瑞脑烟残，沈香火冷。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-709","tags":[]},{"id":"poem-e77fc66d5d4e09feed250aab","title":"尾声","author":"无名氏《宦门子弟错立身》","dynasty":"元","verses":["我和你同心意，愿得百岁镇相随，尽老今生不暂离。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-309","tags":[]},{"id":"poem-e77ff80223dd6ee4b0835191","title":"田漏","author":"林之奇","dynasty":"宋","verses":["古星昏晓中，寒暑已不疑。","田家更置漏，寸晷亦欲知。","汗与水俱滴，身随阴屡移。","谁当哀此劳，往往夺其时。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-d4513fd9-54df-4161-926c-33252808e28a","tags":[]},{"id":"poem-e7810a58cd48c14057fd7aaf","title":"石州慢·寒水依痕","author":"张元干","dynasty":"宋","verses":["寒水依痕，春意渐回，沙际烟阔。","溪梅晴照生香，冷芯数枝争发。","天涯旧恨，试看几许消魂，长亭门外山重叠。","不尽眼中青，是愁来时节。","情切。","画楼深闭，想见东风，暗销肌雪。","辜负枕前云雨，尊前花月。","心期切处，更有多少凄凉，殷勤留与归时说。","到得却相逢，恰经年离别。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-115","tags":["宋词三百首"]},{"id":"poem-e781767c4ddea3ecdc0e7a21","title":"圣果寺","author":"释处默","dynasty":"唐","verses":["路自中峰上，盘回出薜萝。","到江吴地尽，隔岸越山多。","古木丛青蔼，遥天浸白波。","下方城郭近，钟磬杂笙歌。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-聖果寺","tags":[]},{"id":"poem-e78a2721d4b764e58dae2967","title":"上包祭酒","author":"孟郊","dynasty":"唐","verses":["岳岳冠盖彦，英英文字雄。","琼音独听时，尘韵固不同。","春云生纸上，秋涛起胸中。","时吟五君咏，再举七子风。","何幸松桂侣，见知勤苦功。","愿将黄鹤翅，一借飞云空。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-2bbe57c4-65b2-4f16-8039-2e2a70c1316a","tags":[]},{"id":"poem-e78c103460ba16db63ec3553","title":"正月十四日大雪上信国公冢  其一","author":"赵文","dynasty":"宋","verses":["哭得愁云转不晴，山风吹泪欲成冰。","两年不过西州路，今日来登下马陵。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-51b4e119-e0c9-4d56-8aee-5aab5016b284","tags":[]},{"id":"poem-e78cdbdb02f60fa1414e5ef1","title":"庾岭  其二","author":"高吉","dynasty":"宋","verses":["江水悠悠去莫追，个中造道有深机。","我来岂为观鱼说，人笑无钩钓傍矶。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-bdba8044-e45b-4cda-b281-ac3f9b3aa451","tags":[]},{"id":"poem-e79746cb8c54a78caae722d7","title":"登楼","author":"朱斌","dynasty":"唐","verses":["白日依山尽，黄河入海流。","欲穷千里目，更上一层楼。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-19340af6-e25d-41c8-90fc-b465d9be1134","tags":["唐诗三百首","黄河","山水","励志","登楼","写景","哲理","名楼、庙宇","五言绝句"]},{"id":"poem-e79e4372f298e9452c5f909e","title":"贼退示官吏","author":"元结","dynasty":"唐","verses":["昔岁逢太平，山林二十年。","泉源在庭户，洞壑当门前。","井税有常期，日[晏]犹得眠。","忽然遭世变，数岁亲戎旃。","今来典斯郡，山夷又纷然。","城小贼不屠，人贫伤可怜。","是以陷隣境，此州独见全。","使臣将王命，岂不如贼焉。","今彼徴敛者，迫之如火煎。","谁能绝人命，以作时世贤。","思欲委符节，引竿自刺船。","将家就鱼麦，归老江湖边。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-1ce94bde-41ec-42b8-abef-e1e1be55be7c","tags":["唐诗三百首","同情","五言古诗"]},{"id":"poem-e7a8a9971e6df3fa1a4040a6","title":"长安道中早行","author":"张佖","dynasty":"宋","verses":["客离孤馆一灯残，牢落星河欲曙天。","鸡唱未沈函谷月，雁声新度灞陵烟。","浮生已悟庄周蝶，壮志仍输祖逖鞭。","何事悠悠策羸马，此中辛苦过流年。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-ac1bed91-33cd-4efe-a02e-9cd2524e3e50","tags":[]},{"id":"poem-e7b1c22ac3bb481bbfdaae11","title":"夜飞鹊・夜飞鹊慢·河桥送人处","author":"周邦彦","dynasty":"宋","verses":["河桥送人处，凉夜何其。","斜月远堕馀辉。","铜盘烛泪已流尽，霏霏凉露沾衣。","相将散离会，探风前津鼓，树杪参旗。","华骢会意，纵扬鞭、亦自行迟。","迢递路回清野，人语渐无闻，空带愁归。","何意重红满地，遗钿不见，斜径都迷。","兔葵燕麦，向残阳、欲与人齐。","但徘徊班草，欷酹酒，极望天西。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-243","tags":["宋词三百首"]},{"id":"poem-e7b58ce896d7a91e099be75c","title":"传言玉女","author":"施惠《幽闺记》","dynasty":"元","verses":["(外上)得睹天颜，真为主忧臣辱。","(老旦上)皇恩深沐，享千钟重禄。","(旦、小旦上)如今幸得再整银屏金屋。","(合)皇朝重见，太严重睹。","(外)尽日笙歌按玉楼，(老旦)忽朝军马犯皇州，(旦、小旦)但知会取非常乐，(合)须是提防不测忧。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3047","tags":[]},{"id":"poem-e7cedc9b9e2d2c0af20bb280","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["不是我自夸，它自定及第。","着鞭衣锦归，便是荣贵时。","(净)我做婆婆，你做当直度。","(末白)又占有好底。","(合)那时价喜，买炷明香，大家答谢天地。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2596","tags":[]},{"id":"poem-e7cf00eff04801984b48ecfb","title":"题湘潭丞黄子辩哦松轩","author":"张栻","dynasty":"宋","verses":["黄子官居多暇日，吟哦薄暮一窗中。","虽无㶁㶁循除水，但觉飕飕满屋风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-4359c52f-2339-4ce1-a534-7d7adc3f39dc","tags":[]},{"id":"poem-e7daaeffc480bef3c196d0d4","title":"立春前四日天大雷电以雨","author":"释居简","dynasty":"宋","verses":["霹雳如春雨似秋，兰陵冬夜忆黄州。","茂陵封禅期身后，恰恰营成小竹楼。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-9200653b-026e-41bc-95b1-513383f536ab","tags":[]},{"id":"poem-e7dac37c471264e73b4c7f2a","title":"严陵祠","author":"洪子舆","dynasty":"唐","verses":["汉主召子陵，归宿洛阳殿。","客星今安在，隐迹犹可见。","水石空潺湲，松篁尚葱蒨。","岸深翠阴合，川回白云徧。","幽径滋芜没，荒祠幂霜霰。","垂钓想遗芳，掇苹羞野荐。","高风激终古，语理忘荣贱。","方騐道可尊，山林情不变。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-0cc8df3c-e9b4-4a52-80fe-e1b3014da1d8","tags":[]},{"id":"poem-e7e18f9c79ef5ed942aedf7f","title":"送孟八浩然归襄阳二首 二","author":"张子容","dynasty":"唐","verses":["杜门不欲出，久与世情疎。","以此为长策，劝君归旧庐。","醉歌田舍酒，笑读古人书。","好是一生事，无劳献子虚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-e4eb0fd5-78f5-4004-bed3-acd3a786062c","tags":[]},{"id":"poem-e7e78079435b16d0d1f03a2b","title":"边上送友人归宁","author":"曹松","dynasty":"唐","verses":["乡路穿京过，宁心去少同。","日斜寻阔碛，春尽逐归鸿。","独树河声外，凝笳塞色中。","怜君到此处，却背老莱风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-33de29ff-0129-4ff6-a175-529713d046c0","tags":[]},{"id":"poem-e7f1004d1499f51993335bce","title":"哭曲山人","author":"司空曙","dynasty":"唐","verses":["忆昔秋风起，君曾叹逐臣。","何言芳草日，自作九泉人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-f8bd6aed-f7ef-403a-9584-cef60350368d","tags":[]},{"id":"poem-e7f349fbb3bd3d7f1ee4c67a","title":"感遇十二首 二","author":"张九龄","dynasty":"唐","verses":["幽林归独卧，滞虑洗孤清。","持此谢高鸟，因之传远情。","日夕怀空意，人谁感至精。","飞沈理自隔，何所慰吾诚。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-6df38a77-6e5d-43ae-a115-7de36475f53e","tags":["唐诗三百首","寓人","五言古诗","哲理","写鸟","寓言","鸟"]},{"id":"poem-e7fb4f376a3e6d58bc42d605","title":"绣停针","author":"萧德祥《小孙屠》","dynasty":"元","verses":["自从那日，打散鸳鸯侣镇长叹吁。","袖罗红湿胭脂泪，愁到那人提起。","谢老天开方便眼，施小计恰早投机。","自今一步不厮离，在天只愿效于飞，在地同为连理。","(净)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8651","tags":[]},{"id":"poem-e7fefe3e9581c33e1a943245","title":"听曹刚弹琵琶","author":"薛逢","dynasty":"唐","verses":["禁曲新翻下玉都，四弦掁触五音殊。","不知天上弹多少，金凤衔花尾半无。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-c283ce18-2602-4c05-817f-cab9beb010fc","tags":[]},{"id":"poem-e809b7ab1cfd01a67b12d48a","title":"气出唱 其二","author":"曹操","dynasty":"汉","verses":["驾六龙，乘风而行。","行四海，路下之八邦。","历登高山临溪谷，乘云而行。","行四海外，东到泰山。","仙人玉女，下来翱游。","骖驾六龙饮玉浆。","河水尽，不东流。","解愁腹，饮玉浆。","奉持行，东到蓬莱山，上至天之门。","玉阙下，引见得入，赤松相对，四面顾望，视正焜煌。","开玉心正兴，其气百道至。","传告无穷闭其口，但当爱气寿万年。","东到海，与天连。","神仙之道，出窈入冥，常当专之。","心恬澹，无所愒。","欲闭门坐自守，天与期气。","愿得神之人，乘驾云车，骖驾白鹿，上到天之门，来赐神之药。","跪受之，敬神齐。","当如此，道自来。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-10","tags":[]},{"id":"poem-e80ad38c960589daf9fdc626","title":"玉楼春·檀槽碎响金丝拨","author":"欧阳修","dynasty":"宋","verses":["檀槽碎响金丝拨。","露湿浔阳江上月。","不知商妇为谁愁，一曲行人留夜发。","画堂花月新声别。","红蕊调长弹未彻。","暗将深意祝胶弦，唯愿弦弦无断绝。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-680","tags":[]},{"id":"poem-e80f1f2cd4972f652cec310b","title":"遣悲怀三首 三","author":"元稹","dynasty":"唐","verses":["闲坐悲君亦自悲，百年都是几多时。","邓攸无子寻知命，潘岳悼亡犹费词。","同穴窅冥何所望，他生缘会更难期。","唯将终夜长开眼，报荅平生未展眉。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-82f57261-b608-4ee9-8d88-7fde20c49a7a","tags":["唐诗三百首","七言律诗","悼亡"]},{"id":"poem-e80f76ef8729a1ead8c1b3c9","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［生］对：古明君在重贤，古良臣贡举先。","巫咸傅说初皆贱，伊尹曾耕莘上田。","皋陶既举不仁远，四皓出而汉祚安。","恭承执一询遇见，敢不谆谆露胆肝？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8045","tags":[]},{"id":"poem-e810136d75497306ec1cbb71","title":"寄西峰僧","author":"张籍","dynasty":"唐","verses":["松暗水涓涓，夜凉人未眠。","西峰月犹在，遥忆草堂前。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-4c937660-3aa1-4f1a-b39d-c41c717162ef","tags":[]},{"id":"poem-e812a66596382eef2eb6fb76","title":"有感","author":"牟融","dynasty":"唐","verses":["盛世嗟沈伏，中情怏未舒。","途穷悲阮籍，病久忆相如。","无客空尘榻，闲门闭草庐。","不胜岑绝处，高卧半床书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-95329e84-1101-42c8-a307-221afe9adedf","tags":[]},{"id":"poem-e816150a953ce817ea6393fd","title":"感秋别怨","author":"卢仝","dynasty":"唐","verses":["霜秋自断魂，楚调怨离分。","魄散瑶台月，心随巫峡云。","蛾眉谁共画，凤曲不同闻。","莫似湘妃泪，斑斑点翠裙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-f548c1e1-4ec6-450e-8a5e-bf7f91fa1248","tags":[]},{"id":"poem-e819f77d8655d5eb3dab1252","title":"番女怨·碛南沙上惊雁起","author":"温庭筠","dynasty":"唐","verses":["碛南沙上惊雁起，飞雪千里。","玉连环，金镞箭，年年征战。","画楼离恨锦屏空，杏花红。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-12","tags":[]},{"id":"poem-e81fea8c9d0d78a7fd25aed9","title":"寄题傅钦之济源别业","author":"司马光","dynasty":"宋","verses":["县郭遥相望，修篁百亩余。","林间清济水，门外太行车。","道胜随宜足，身闲与世疏。","何时容命驾，采蕨钓肥鱼。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-95a55535-799f-4a9a-8398-53b203b95350","tags":[]},{"id":"poem-e829e1f101d40a27814cf039","title":"临江仙","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(旦上)父母一朝抛弃，夫妻两下分张。","哥哥嫂嫂铁心肠，交奴受万千磨障。","今日我身分娩，始知恩爱难忘。","自将心事细思量，眼下这般情况。","我儿，生下你来，受了万千疼痛苦楚。","想我母亲养我下来，也受这般苦楚。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8927","tags":[]},{"id":"poem-e82bd3be8c7e71d7e9ff4307","title":"同程九早入中书","author":"钱珝","dynasty":"唐","verses":["汉家贤相重英奇，蟠木何材也见知。","不意云霄能自致，空惊鹓鹭忽相随。","腊雪初明柏子殿，春光欲上万年枝。","独惭皇鉴明如日，未厌春光向玉墀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-e4449fbb-cf45-43a2-b3ff-4ee886423be1","tags":[]},{"id":"poem-e837b1799a5817fda621ecc6","title":"云峰  其一","author":"陈岩","dynasty":"宋","verses":["诘朝云出雨如倾，向晚云归日逗明。","不比世间翻覆手，望云人要验阴晴。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-16d21182-5e18-48cf-b999-a7af459d86db","tags":[]},{"id":"poem-e84c174d2e60e83c00f0e707","title":"西江月·味过华林芳蒂","author":"仲殊","dynasty":"宋","verses":["味过华林芳蒂，色兼阳井沈朱。","轻匀绛蜡裹团酥。","不比人间甘露。","神鼎十分火枣，龙盘三寸红珠。","清含冰蜜洗云腴。","只恐身轻飞去。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-905","tags":[]},{"id":"poem-e84ea926ad58cd1f17fd2c84","title":"赋得垣衣","author":"李益","dynasty":"唐","verses":["漠漠复霏霏，为君垣上衣。","昭阳辇下草，应笑此生非。","掩蔼青春去，苍茫白露稀。","犹胜萍逐水，流浪不相依。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-eb0f6c98-600f-490d-aab0-8e2eedcf33b4","tags":[]},{"id":"poem-e853d016bf7ff7a8aa1c60e4","title":"金山  其二","author":"释居简","dynasty":"宋","verses":["不占南徐地，遥分北固天。","削琼标巨浸，坚壁下长川。","城柝偏遥夜，淮烽直近壖。","建炎天子圣，翠辇到层颠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-1e837cc9-5d74-445e-a7ad-8fded08a3df2","tags":[]},{"id":"poem-e85b9d04d2fb9ad575a4933c","title":"相见欢·无言独上西楼","author":"李煜","dynasty":"五代","verses":["无言独上西楼，月如钩。","寂寞梧桐深院，锁清秋。","剪不断，理还乱，是离愁。","别是一般滋味，在心头。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-15","tags":[]},{"id":"poem-e85bea4df931dc3283dda0b9","title":"奉和圣制荅张说扈从南出雀鼠谷","author":"梁升卿","dynasty":"唐","verses":["何意重关道，千年过圣皇。","幽林承睿泽，闲客见清光。","日御仙途远，山灵寿域长。","寒云入晋薄，春树隔汾香。","国佐同时雨，天文属岁阳。","从来汉家盛，未若此巡方。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-99c735da-a0c6-4e4a-95e9-df063087ef5b","tags":[]},{"id":"poem-e86677d5ae8d141303f5bee7","title":"离歌辞五首  其四","author":"徐铉","dynasty":"宋","verses":["暂别劳相送，佳期愿莫违。","朱颜不须老，留取待郎归。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-d8056244-45fe-4f7c-9d0a-85cee8a335d2","tags":[]},{"id":"poem-e867c9d5e870ba6342a7099f","title":"送僧游宣州","author":"皎然","dynasty":"唐","verses":["楚山千里一僧行，念尔初缘道未成。","莫向舒姑泉口泊，此中呜咽为伤情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-0c49dce5-ed9c-43dc-8375-bed3229dc819","tags":[]},{"id":"poem-e867df15537cc760cffca98c","title":"木兰花・玉楼春·辘轳轭轭门前井","author":"李石","dynasty":"宋","verses":["辘轳轭轭门前井。","不道隔窗人睡醒。","柔弦无力玉琴寒，残麝彻心金鸭冷。","一莺啼破帘栊静。","红日渐高槐转影。","起来情绪寄游丝，飞绊翠翘风不定。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-270","tags":[]},{"id":"poem-e869ddf8bb8d3b4e96741e4c","title":"诉衷情·桃花流水漾纵横","author":"毛文锡","dynasty":"五代","verses":["桃花流水漾纵横，春昼彩霞明。","刘郎去，阮郎行，惆怅恨难平。","愁坐对云屏，算归程。","何时携手洞边迎，诉衷情。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-28","tags":[]},{"id":"poem-e87914273c2c58026af28213","title":"送潘三入京","author":"周瑀","dynasty":"唐","verses":["故人嗟此别，相送出烟坰。","柳色分官路，荷香入水亭。","离歌未尽曲，酌酒共忘形。","把手河桥上，孤山日暮青。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-4880b25c-7b97-489c-adc7-68049ef84083","tags":[]},{"id":"poem-e8873896b83ecf5385ff27e8","title":"萧二十三赴歙州婚期二首 二","author":"卢仝","dynasty":"唐","verses":["南方山水生时兴，教有新诗得寄余。","路带长安迢遰急，多应不逐使君书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-4c0cf5ac-21e0-44fe-9a34-b3d4f1912d5a","tags":[]},{"id":"poem-e89332020dff47c3694dcd91","title":"书补之梅","author":"王柏","dynasty":"宋","verses":["玉质敷腴宫样妆，风流终媿水云乡。","一邨飞落人间世，添却逃禅百倍香。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-9efc7a11-2cfc-4917-94d5-9ed91388e7e1","tags":[]},{"id":"poem-e89725ae88b331ae41bb9e0d","title":"题贾岛吟诗台","author":"归仁","dynasty":"唐","verses":["此台如可废，此恨有谁平。","纵使迷青草，终难没旧名。","天悲朝雨色，岳哭夜猨声。","不是心偏苦，应关自古情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-e59aed37-0336-4982-96bd-a1bd468312ed","tags":[]},{"id":"poem-e8974de86ac77e609d0428a3","title":"好事近·何路向家园","author":"纳兰性德","dynasty":"清","verses":["何路向家园，历历残山剩水。","都把一春冷淡，到麦秋天气。","料应重发隔年花，莫问花前事。","纵使东风依旧，怕红颜不似。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-32","tags":[]},{"id":"poem-e89b7187cf44840e3360e242","title":"菩萨蛮·曲门南与鸣珂接","author":"贺铸","dynasty":"宋","verses":["曲门南与鸣珂接。","小园绿径飞胡蝶。","下马访婵娟。","笑迎妆阁前。","鹧鸪声几叠。","艳艳金蕉叶。","未许被香鞯。","月生楼外天。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-16","tags":[]},{"id":"poem-e89cd8b24a079962413d5bad","title":"病起四诗 二止酒","author":"陈造","dynasty":"宋","verses":["少日良束修，但识名教乐。","谁令忧患后，颇复近杯勺。","嚚号或跳梁，扶携取谐谑。","兴来偶一适，事过含余怍。","向非病鼎至，或未悟狂药。","不知黍麦毒，终乃蓳葛若。","腐肠自浸渐，履虺尚歌咢。","覆觞吾已后，遽觉今胜昨。","此衷天启之，相予固不薄。","卒岁办僧过，茗粥安淡泊。","时醉床头经，妙意翔碧落。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-ba78e60d-06b4-4380-8319-8114d79c69c1","tags":[]},{"id":"poem-e89da5ab7eff2b5a81408562","title":"横吹曲辞 折杨柳","author":"韦承庆","dynasty":"唐","verses":["万里边城地，三春杨柳节。","叶似镜中眉，花如关外雪。","征人远乡思，倡妇高楼别。","不忍掷年华，含情寄攀折。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-0e651edd-1bc8-49c9-bd85-b49df84c9743","tags":[]},{"id":"poem-e89e6878335f7d6cdfdbe8d3","title":"蝶恋花·独倚危楼风细细","author":"欧阳修","dynasty":"宋","verses":["独倚危楼风细细。","望极离愁，黯黯生天际。","草色山光残照里。","无人会得凭阑意。","也拟疏狂图一醉。","对酒当歌，强饮还无味。","衣带渐宽都不悔。","况伊销得人憔悴。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-172","tags":["宋词三百首"]},{"id":"poem-e8a8311bf52749845a5c7685","title":"过秦楼·水浴清蟾","author":"周邦彦","dynasty":"宋","verses":["水浴清蟾，叶喧凉吹，巷陌马声初断。","闲依露井，笑扑流萤，惹破画罗轻扇。","人静夜久凭阑，愁不归眠，立残更箭。","叹年华一瞬，人今千里，梦沈书远。","空见说、鬓怯琼梳，容销金镜，渐懒趁时匀染。","梅风地溽，虹雨苔滋，一架舞红都变。","谁信无，为伊才减江淹，情伤荀倩。","但明河影下，还看稀星数点。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-231","tags":["宋词三百首"]},{"id":"poem-e8a8371e739d5f266635e059","title":"陌上桑","author":"曹操","dynasty":"汉","verses":["驾虹霓，乘赤云，登彼九疑历玉门。","济天汉，至昆仑，见西王母谒东君。","交赤松，及羡门，受要秘道爱精神。","食芝英，饮醴泉，柱杖桂枝佩秋兰。","绝人事，游浑元，若疾风游欻翩翩。","景未移，行数千，寿如南山不忘愆。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-15","tags":[]},{"id":"poem-e8b1c896241fd65f58acbf16","title":"定西番·年少登瀛词客","author":"张先","dynasty":"宋","verses":["年少登瀛词客，飘逸气，拂晴霓。","尽带江南春色、过长淮。","一曲艳歌留别，翠蝉摇宝钗。","此后吴姬难见、且徘徊。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-347","tags":[]},{"id":"poem-e8b3e0e003d9eb65ba3fc40a","title":"鹧鸪天·水阔天低雁字横","author":"谢逸","dynasty":"宋","verses":["水阔天低雁字横。","小春时节晚寒清。","梅梢月上纷纷白，竹坞风来冉冉轻。","人似玉，酒如渑。","入关意气喜风生。","坐中有客联镳去，谁唱阳关第四声。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-638","tags":[]},{"id":"poem-e8b675eb9810796ea94b59dd","title":"再次韵  其二","author":"陈造","dynasty":"宋","verses":["覆觞课五升，秘诀不待传。","百里三万家，优主师帅权。","坐肉荒岁骨，岂但医十全。","高郎径刺史，况论担弛肩。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-cc330c76-c152-4fda-8d84-fe0372f6a583","tags":[]},{"id":"poem-e8bec09f421a2a3f2ca83ebc","title":"张荃翁赴浦江丞而丧耦唁荃翁谢获轩见寄  其二","author":"释居简","dynasty":"宋","verses":["绝笑诸郎似乃翁，荃翁又自去哦松。","捄焚赏必先焦额，欲雨香非后土龙。","徵调苦多忘惜日，燮调伤煖不成冬。","吴江短楫华亭月，称副茎虀藐万锺。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-c94daae8-5c00-48eb-bf85-f2bc835d5aa3","tags":[]},{"id":"poem-e8c6896e5db10c8689062a88","title":"使君沈虞卿宗丞命赋郡圃罗汉树其树叶如杨梅经冬不雕生子若罗汉然使君云奇特古怪前所未见也","author":"林宪","dynasty":"宋","verses":["参云亭前罗汉树，非桧非杉独雄据。","苍皮剥落珊瑚寒，错节轮囷海花蠹。","修圆佛指叶沃光，刺历虾筒槎倒竖。","铜柯不受鸱蝮穿，翠葆还容藤蔓附。","藏牙敛翼方屈蟠，奋鬣张鳞忽驰骛。","突如破浪六鼇回，蜿若惊雷蛰蛟煦。","摩空飕飕永夏凉，薄雾惨惨晚秋雨。","白猨叫月时出没，紫凤栖烟乍飞举。","开花琐碎儿女笑，结子模糊罗汉具。","威仪庄肃初入定，向背跏趺欣共住。","蒙头大似安禅时，瞑目还同摩顶处。","得非天台五百仙，此地钵提曾得度。","偶然一念落树石，不觉形骸成布露。","何时收拾过石桥，未免根株伴龙顾。","更疑地主屈将军，开辟岩荒肇城宇。","剪除魔怪迎道猷，飞锡半千此焉驻。","神通堕在造化中，千载英灵飞不去。","犀坚久矣耐风霆，樗散非徒免斤斧。","盆山秀耸不足论，猊座婆娑通一路。","峥嵘下笑桃李繁，奇怪应须鬼神护。","使君自是名世才，善政报成多暇豫。","悠然领客上参云，篆隶传观酒深注。","平生好古邱壑会，指树轩渠命之赋。","我无文章光燄长，搜搅经时乏佳趣。","昨宵梦游兹树巅，环视谿山莽回互。","上云变幻舞龙鸾，下风清和写韶濩。","最高峰在樛枝底，方广寺随纤叶寓。","一枝一叶一沙界，应供各谈无义句。","启予一啸谁划然，八表泠泠树掀翥。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-f8f368ee-c1a9-4e0c-b89f-dfacc276ad69","tags":[]},{"id":"poem-e8ca3beb0febeaa168a40019","title":"忆江南·宿双林禅院有感","author":"纳兰性德","dynasty":"清","verses":["心灰尽、有发未全僧。","风雨消磨生死别，似曾相识只孤檠，情在不能醒。","摇落后，清吹那堪听。","淅沥暗飘金井叶，乍闻风定又钟声，薄福荐倾城。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-158","tags":[]},{"id":"poem-e8d201fc47c4271c4ed895a6","title":"临江仙·试凭阑干春欲暮","author":"史浩","dynasty":"宋","verses":["试凭阑干春欲暮，桃花点点胭脂。","故山凝望水云迷。","数堆苍玉髻，千顷碧琉璃。","我本清都闲散客，蓬莱未是幽奇。","明朝归去鹤齐飞。","三山乘缥缈，海运到天池。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-177","tags":[]},{"id":"poem-e8d2557ec347d854cb6fd8f9","title":"移梅","author":"释居简","dynasty":"宋","verses":["雪消时候带花移，花笑移迟不振奇。","今岁弗须嫌早计，趁它一点未开时。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-8619515b-8c69-4577-82a3-3ae590d7eba7","tags":[]},{"id":"poem-e8d7855d84094a7ffccb26f7","title":"林省吾挽辞","author":"王柏","dynasty":"宋","verses":["羌若人兮大带而深衣，张拱徐趋兮俨乎其若思。","动有则兮神定，澹无欲兮心夷。","便儇嵚巇之纷吾前兮，醢鸡起灭。","忠信传习之省吾躬兮，圣贤我师。","伊春阳之冉冉兮，生意方懋。","何雪霜之不仁兮，荃兰遽萎。","搴三后之纯英兮，时不得而荣瘁。","抱太极而永归兮，哀与我之其谁。","云沈沈兮凄𪩘，风棱棱兮断澌。","长田长田兮，寂寂永夜。","畅旨独立兮，千古名垂。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-bca5a092-b748-493f-9c57-a86196a0773e","tags":[]},{"id":"poem-e8dd2d7f65d58929e0c0146f","title":"燕衔泥","author":"冯著","dynasty":"唐","verses":["双燕碌碌飞入屋，屋中老人喜燕归。","裴回绕我床头飞，去年为尔逐黄雀。","雨多屋漏泥土落，尔莫厌老翁茅屋低，梁头作窠梁下栖。","尔不见东家黄鷇鸣啧啧，蛇盘瓦沟鼠穿壁。","豪家大屋尔莫居，娇儿少妇采尔雏。","井旁写水泥自足，衔泥上屋随尔欲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-891b2c80-f3fc-4841-93a9-6d68605e175a","tags":[]},{"id":"poem-e8e403b4972b606ccd906bb3","title":"句  其一","author":"鲜于侁","dynasty":"宋","verses":["人寻载酒地，雨破看花期。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-6ba62cf1-5f24-4892-9059-3becfbdb6f06","tags":[]},{"id":"poem-e8e5a3b883586bdd0622b230","title":"陪卢判官水堂夜宴","author":"皎然","dynasty":"唐","verses":["暑气当宵尽，裴回坐月前。","静依山堞近，凉入水扉偏。","久是栖林客，初逢佐幕贤。","爱君高野意，烹茗钓沦涟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-e251843e-76da-430c-949e-eb57d8fdf72a","tags":[]},{"id":"poem-e8f0e60013af6785559231ec","title":"河传·花落","author":"孙光宪","dynasty":"五代","verses":["花落，烟薄，谢家池阁。","寂寞春深，翠蛾轻敛意沉吟。","沾襟，无人知此心。","玉炉香断霜灰冷，帘铺影，梁燕归红杏。","晚来天，空悄然。","孤眠，枕檀云髻偏。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-48","tags":[]},{"id":"poem-e8f589f7061dbccde1dcef87","title":"壮观","author":"米芾","dynasty":"宋","verses":["临南山猗陟北岵，抚壮胜猗遗万古。","漫漫苍苍穹无所，奕奕嶪嶪踪奇度。","逶迤猗前征，盘礴猗后驻。","奋迅猗奔驶，却约猗畔顾。","环旋猗抱卷，引伸猗就旅。","雾释猗离掩，云乘猗平举。","瞭瞭猗蟾辉，悒悒猗蒸雨。","鬰鬰猗阳春，莽莽猗玉露。","爚爚猗午停，翳翳猗酉去。","领吾侪猗并舆步，却飞仙猗不遐慕，癯其形猗久何苦。","便莫便猗遵坦路，适莫适猗破心阻。","乐莫乐猗频会遇，莫莞藤猗撷芳藇。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-055c42a7-1dcf-4194-9ed8-3647b280c43b","tags":[]},{"id":"poem-e8f680b3555fe5b99fbbcd4e","title":"沁园春","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["赵女姿容，蔡邕文业，两月夫妻。","奈朝廷黄榜，遍招贤士，高堂严命，强赴春闱。","一举螯头，再婚牛氏，利绾名牵竟不归。","饥荒岁，双亲俱丧，此际实堪悲。","堪悲赵女支持，剪下香云送舅姑。","罗裙包土，筑成坟墓；琵琶写怨，竟往京畿。","孝矣伯喈，贤哉牛氏，书馆相逢最惨凄。","重庐墓，一夫二妇，旌表耀门闾。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4908","tags":[]},{"id":"poem-e9032d599c20435aae1f5a81","title":"九思·逢尤","author":"王逸","dynasty":"汉","verses":["悲兮愁，哀兮忧！","天生我兮当暗时，被诼谮兮虚获尤。","心烦愦兮意无聊，严载驾兮出戏游。","周八极兮历九州，求轩辕兮索重华。","世既卓兮远眇眇，握佩玖兮中路躇。","羡咎繇兮建典谟，懿风后兮受瑞图。","愍余命兮遭六极，委玉质兮于泥涂。","遽傽遑兮驱林泽，步屏营兮行丘阿。","车𫐄折兮马虺颓，惷怅立兮涕滂沱。","思丁文兮圣明哲，哀平差兮迷谬愚。","吕傅举兮殷周兴，忌嚭专兮郢吴虚。","仰长叹兮气噎结，悒殟绝兮咶复苏。","虎兕争兮于廷中，豺狼斗兮我之隅。","云雾会兮日冥晦，飘风起兮扬尘埃。","走鬯罔兮乍东西，欲窜伏兮其焉如？","念灵闺兮隩重深，原竭节兮隔无由。","望旧邦兮路逶随，忧心悄兮志勤劬。","魂茕茕兮不遑寐，目眽眽兮寤终朝。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-56","tags":[]},{"id":"poem-e90ce92c1100b8c82edf4680","title":"下第别令狐员外","author":"马戴","dynasty":"唐","verses":["论文期雨夜，饮酒及芳晨。","坐叹百花发，潜惊双鬓新。","旧交多得路，别业远仍贫。","便欲辞知己，归耕海上春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-e73ec8cc-adc7-48de-8cd5-8780f364700c","tags":[]},{"id":"poem-e9139770ca826c92c3352e17","title":"偈","author":"道恒","dynasty":"唐","verses":["不要三乘要祖宗，三乘不要与君同。","君今欲会通宗旨，后夜猿啼在乱峰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-5ee4e22b-5968-485c-ae15-eeaaf6a696e3","tags":[]},{"id":"poem-e91646107ce4809a5979a465","title":"菩萨蛮·花冠频鼓墙头翼","author":"孙光宪","dynasty":"五代","verses":["花冠频鼓墙头翼，东方淡白连窗色。","门外早莺声，背楼残月明。","薄寒笼醉态，依旧铅华在。","握手送人归，半拖金缕衣。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-1","tags":[]},{"id":"poem-e91911a5e12b4885e82c5826","title":"丑奴儿令・采桑子·红楼紫陌青春路","author":"康与之","dynasty":"宋","verses":["红楼紫陌青春路，柳色皇州。","月淡烟柔。","袅袅亭亭不自由。","旧时扶上雕鞍处，此地重游。","总是新愁。","柳自轻盈水自流。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-298","tags":[]},{"id":"poem-e91e572882de75a87b2b146e","title":"寄道者","author":"赵嘏","dynasty":"唐","verses":["洞庭先生归路长，海云望极春茫茫。","别来几度向蓬岛，自傍瑶台折灵草。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-f0b26d34-d1b8-42a9-99b4-d911b5365c17","tags":["洞庭湖"]},{"id":"poem-e9211ed8aa69e2e69a9b76e5","title":"定西番·鸡禄山前游骑","author":"孙光宪","dynasty":"五代","verses":["鸡禄山前游骑，边草白，朔天明，马蹄轻。","鹊面弓离短韔，弯来月欲成。","一只鸡鹘云外，晓鸿惊。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-28","tags":[]},{"id":"poem-e92560bde1e2a52a6926ff67","title":"马诗二十三首 二十二","author":"李贺","dynasty":"唐","verses":["汗血到王家，随鸾撼玉珂。","少君骑海上，人见是青骡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-e08d02a9-041f-4864-a26c-6e6f5a612d5a","tags":[]},{"id":"poem-e9275b248409d934c59d4988","title":"同望幸新亭赐钱公宴","author":"李憕","dynasty":"唐","verses":["感梦通玄化，覃恩降紫宸。","赐钱开汉府，分帛醉尧人。","地隔朝宗庆，亭临卜洛新。","行看广云雨，二月次东巡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-d10809a9-e7c1-4d27-8759-b4b32fe17fd4","tags":[]},{"id":"poem-e9287a07f3efb96bad4994b3","title":"瑞上人血书莲经报亲","author":"释了惠","dynasty":"宋","verses":["二千年前血滴滴，今日分明重指出。","所生父母知不知，一二三四五六七。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-d6468c09-86ec-4111-98dd-e7fee8485e1e","tags":[]},{"id":"poem-e92919526e256aa512397c85","title":"题曾氏山园十一咏 吟风桥","author":"张栻","dynasty":"宋","verses":["桥边风月佳，俯仰有余思。","无忘履冰心，方识吟风意。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-ac3e52ba-c8b3-458c-9a06-f6d2da3291c7","tags":[]},{"id":"poem-e92ed4dcc03bbe235cae739c","title":"答钟弱翁","author":"牧童","dynasty":"宋","verses":["草铺横野六七里，笛弄晚风三四声。","归来饱饭黄昏后，不脱蓑衣卧月明。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-答鍾弱翁","tags":[]},{"id":"poem-e93133faf7ec65dadd3298aa","title":"持钵  其三","author":"释居简","dynasty":"宋","verses":["颠风挟玄霜，跋扈清溪阴。","长年把船尾，铁面抵弗禁。","面皴不暇问，腕裂龟文深。","手中老篙竹，出水冰淋淋。","一步一千里，进寸或退寻。","抵死为食谋，俛首潜呻吟。","劳人冻入骨，寸心攒万针。","乐哉田舍郎，坐拥廪若林。","强使损绪余，瞪目如病瘖。","所得不盈把，粒米敌数金。","沈思耕者志，岂异舟子心。","其谁受此施，观此受施箴。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-d9043ea7-8f6a-47a1-8b59-bf26e8186e2e","tags":[]},{"id":"poem-e93207f1df70b827ff1bf6e1","title":"采桑子·巂周声里严关峙","author":"纳兰性德","dynasty":"清","verses":["巂周声里严关峙，匹马登登，乱踏黄尘。","听报邮签第几程。","行人莫话前朝事，风雨诸陵，寂寞鱼灯。","天寿山头冷月横。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-211","tags":[]},{"id":"poem-e932c2bd72683acd32c2a860","title":"春日紫岩山期客不至","author":"徐铉","dynasty":"宋","verses":["郊外春华好，人家带碧溪。","浅莎藏鸭戏，轻霭隔鸡啼。","掩映红桃谷，夤缘翠柳堤。","王孙竟不至，芳草自萋萋。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-678b42ec-6442-4a8f-8514-d2e96c7b3871","tags":[]},{"id":"poem-e93f2fa666ecc4e2458e361d","title":"和明道人宿山寺","author":"徐铉","dynasty":"宋","verses":["闻道经行处，山前与水阳。","磬声深小院，灯影迥高房。","落宿依楼角，归云拥殿廊。","羡师闲未得，早起逐班行。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-2472eee6-3869-49e3-9d96-7b7da5899588","tags":[]},{"id":"poem-e93f8ed533543d1796fd69bc","title":"陈氏童子草书歌","author":"皎然","dynasty":"唐","verses":["书家孺子有奇名，天然大草令人惊。","僧虔老时把笔法，孺子如今皆暗合。","飙挥电洒眼不及，但觉毫端鸣飒飒。","有时作点险且能，太行片石看欲崩。","偶然长掣浓入燥，少室枯松欹不倒。","夏室炎炎少人欢，山轩日色在阑干。","桐花飞尽子规思，主人高歌兴不至。","浊醪不饮嫌昏沈，欲玩草书开我襟。","龙爪状奇鼠须锐，水牋白皙越人惠。","王家小令草最狂，为予洒出惊腾势。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-d82ba80c-aea7-4745-8113-a3632baf5248","tags":[]},{"id":"poem-e9403513df96d19116d171c4","title":"点绛唇·手抚归鸿","author":"毛滂","dynasty":"宋","verses":["手抚归鸿，坐临烟雨帘旌润。","气清天近。","云日温阑楯。","压玉浮金，一醉留青鬓。","风光胜。","淡妆人靓。","眉黛生秋晕。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-851","tags":[]},{"id":"poem-e941ab99316fe6a099fd4992","title":"宿九华化成寺庄","author":"泠然","dynasty":"唐","verses":["佛寺孤庄千嶂间，我来诗境强相关。","岩边树动猿下涧，云里锡鸣僧上山。","松月影寒生碧落，石泉声乱喷潺湲。","明朝更蹑层霄去，誓共烟霞到老闲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-2f55c11b-e673-49e6-a099-8c374336da3a","tags":[]},{"id":"poem-e945d2432f5e4d3a061f31b0","title":"赠禅师","author":"薛能","dynasty":"唐","verses":["梦想青山寺，前年住此中。","夜堂吹竹雨，春地落花风。","旧句师曾见，清斋我亦同。","浮生蹇莫问，辛苦未成功。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-8303cd6a-d38e-420a-98a4-ccd407ef8d73","tags":[]},{"id":"poem-e94993e7af50298a820764e4","title":"横吹曲辞 望行人","author":"张籍","dynasty":"唐","verses":["秋风窗下起，旅雁向南飞。","日日出门望，家家行客归。","无因见边使，空待寄寒衣。","独闭青楼暮，烟深鸟雀稀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ce87b1d6-f5db-47fd-a979-034eb4888e26","tags":[]},{"id":"poem-e94d7e346c918026abb8d5e3","title":"题曾氏山园十一咏 北山","author":"张栻","dynasty":"宋","verses":["南山烟雨霏，北山风露多。","衣沾非所惜，屦湿知如何。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-9a06dfec-d919-4646-850f-73ab5ee8e61d","tags":[]},{"id":"poem-e94d94f688fea544a575e4d0","title":"对雨书怀走邀许十一簿公","author":"杜甫","dynasty":"唐","verses":["东岳云峰起，溶溶满太虚。","震雷飜幕燕，骤雨落河鱼。","座对贤人酒，门听长者车。","相邀媿泥泞，骑马到阶除。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-fea6e004-d905-4fa0-9f6c-c813af7862e6","tags":[]},{"id":"poem-e987686f519b4a88e355a892","title":"送魏舍人仲甫为蕲州判官","author":"徐铉","dynasty":"宋","verses":["从事蕲春兴自长，蕲人应识紫微郎。","山资足后抛名路，莼菜秋来忆故乡。","以道卷舒犹自适，临戈谈笑固无妨。","如闻郡阁吹横笛，时望青谿忆野王。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-0041e40e-ab02-42b1-b519-b774f1c53172","tags":[]},{"id":"poem-e99b80dc37db5c40973997b1","title":"浣溪沙·飞鹊台前晕翠蛾","author":"黄庭坚","dynasty":"宋","verses":["飞鹊台前晕翠蛾。","千金新买帝青螺。","最难如意为情多。","几处泪痕留醉袖，一春愁思近横波。","远山低尽不成歌。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-820","tags":[]},{"id":"poem-e9a776ba574b7eeb30037031","title":"古杭感事  其一","author":"王镃","dynasty":"宋","verses":["国事雕零王气衰，东南豪杰竟何之。","云寒废殿排班石，草卧前朝记事碑。","沙涨浙江龙去远，天宽北阙凤归迟。","可怜不老吴山月，曾照官家宠幸时。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-f3c855c5-a4b6-4388-9df4-f488a246ac0d","tags":[]},{"id":"poem-e9a7f0131be7f1710652873d","title":"送郭司仓","author":"王昌龄","dynasty":"唐","verses":["映门淮水绿，留骑主人心。","明月随良掾，春潮夜夜深。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-送郭司倉","tags":[]},{"id":"poem-e9aecac72451620e4e4da97d","title":"兵要望江南 医方第二十九（十六首） 四","author":"易静","dynasty":"唐","verses":["金刃重，速翦马牛毛。","二件一同烧作末，敷之血止自然消，皮血便坚牢。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-a00607cf-9e22-45a6-9b4c-84ecee29a78f","tags":[]},{"id":"poem-e9b0baf64a5e76439377be03","title":"浣溪沙·始待空冬岁不华","author":"程大昌","dynasty":"宋","verses":["始待空冬岁不华。","还教呈瑞怨贫家。","若为高下总无嗟。","日照华檐晴后雨，风吹飞絮腊前花。","天公何事不由他。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-227","tags":[]},{"id":"poem-e9bd8ba4c10f8ff8b981da9a","title":"和钱秘监旅居秋怀二首  其二","author":"徐铉","dynasty":"宋","verses":["闲静无凡客，开罇共醉醒。","琴弹碧玉调，书展太玄经。","酒熟看黄菊，诗成写素屏。","晚来萧洒甚，山鸟下中庭。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-6f3bc529-65f1-4a6b-b5f3-f3ef4254a291","tags":[]},{"id":"poem-e9c22e9fbc4485216ff57744","title":"过多福寺次王龟龄壁间韵","author":"熊应亨","dynasty":"宋","verses":["七尺枯藤手自摩，闲过僧寺坐横坡。","花开曲径霜前密，云压层城雨后多。","田舍竹林分鹫岭，山城芦水漾鱼波。","禅床处处堆黄叶，独剩寒松不改柯。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-a573dc2d-c0c1-4bad-ae8c-d8704382107e","tags":[]},{"id":"poem-e9c4b6d298a88eb0d9aed63e","title":"力疾山下吴邨看杏花十九首 十五","author":"司空图","dynasty":"唐","verses":["亦知王大是昌龄，杜二其如律韵清。","还有酸寒堪笑处，拟夸朱绂更峥嵘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-0b09b1ab-864e-40ac-ab19-32f75c91d3ab","tags":[]},{"id":"poem-e9cae989d138a8635bf25f11","title":"丽春","author":"杜甫","dynasty":"唐","verses":["百草竞春华，丽春应最胜。","少须好颜色，多漫枝条賸。","纷纷桃李枝，处处总能移。","如何贵此重，却怕有人知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-ccea1790-b4a4-422a-b1f0-2cd37caad120","tags":["花草","春天"]},{"id":"poem-e9d5d5dab64bf10f0fdae5a4","title":"渡中江望石城泣下","author":"后主煜","dynasty":"唐","verses":["江南江北旧家乡，三十年来梦一场。","吴苑宫闱今冷落，广陵台殿已荒凉。","云笼远岫愁千片，雨打归舟泪万行。","兄弟四人三百口，不堪闲坐细思量。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-6533dc36-cc73-4798-b24a-fbff04fc2a85","tags":["抒情","伤怀"]},{"id":"poem-e9d72d6027088303d5c6dfe4","title":"郊庙歌辞 武后享清庙乐章十首 第四迎神","author":"不详","dynasty":"唐","verses":["敬奠苹藻，式罄虔襟。","洁诚斯展，伫降灵歆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-eb8e35db-a91a-46ca-8cde-7864b5e5e249","tags":[]},{"id":"poem-e9d9652ca1cdf4c81a9ea66c","title":"题招隐寺即戴颙旧宅","author":"李涉","dynasty":"唐","verses":["两崖古树千般色，一井寒泉数丈冰。","欲问前朝戴居士，野烟秋色是丘陵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-76e3723a-45f4-4321-bbe8-7c11b533870b","tags":[]},{"id":"poem-e9e42f93cb48bfba985cb748","title":"长洲苑","author":"孙逖","dynasty":"唐","verses":["吴王初鼎峙，羽猎骋雄才。","辇道阊门出，军容茂苑来。","山从列嶂转，江自绕林回。","劒骑缘汀入，旌门隔屿开。","合离纷若电，驰逐溢成雷。","胜地虞人守，归舟汉女陪。","可怜夷漫处，犹在洞庭隈。","山静吟猿父，城空应雉媒。","戎行委乔木，马迹尽黄埃。","揽涕问遗老，繁华安在哉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-6c7fd6e3-4956-4dad-9c0d-d336cb609602","tags":["洞庭湖"]},{"id":"poem-e9f1508eeb808b3223428aae","title":"水殿采菱歌","author":"鲍溶","dynasty":"唐","verses":["宫鸦叫赤光，潮声入宫宫影凉。","火华啼露卷横塘，金堤四合宛柔扬。","美人荷裙芙蓉妆，柔荑萦雾櫂龙航。","采莲一声歌态长，青丝结眼捕鸳鸯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-6591c871-c724-42c1-8038-205060c93540","tags":[]},{"id":"poem-e9f678854696382f30ce3ba9","title":"都亭驿送郭判官之幽州幕府","author":"李端","dynasty":"唐","verses":["幕府参戎事，承明伏奏归。","都亭使者出，杯酒故人违。","细雨沾官骑，轻风拂客衣。","还从大夫后，吾党亦光辉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-89a5fd37-28dd-45c0-8b3f-b9165559b092","tags":[]},{"id":"poem-ea01052a34352b80701472c3","title":"咏史诗 陈宫","author":"胡曾","dynasty":"唐","verses":["陈国机权未可涯，如何后主恣娇奢。","不知即入宫中井，犹自听吹玉树花。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-3b7679ae-244f-4bf8-b15e-eca75faf6412","tags":[]},{"id":"poem-ea1070368326b9a0d014c9cf","title":"永明山居诗（六十九首） 五","author":"延寿","dynasty":"唐","verses":["心地须教合死灰，藏机泯迹绝梯媒。","芳兰祇为因香折，良木多从被直摧。","寒逼花枝红未吐，日融水面绿全开。","支颐独坐经窗下，一片云闲入户来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-8aaca8ee-a0df-4ff9-9c8a-293252d10e46","tags":[]},{"id":"poem-ea16c44aacd3145d45c72210","title":"答东坡居士","author":"释法泉","dynasty":"宋","verses":["指出明明是甚么，举头鹞子穿云过。","从来这碗最希奇，解问灯人能几个。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-31248840-b59f-4190-a051-bd124412f121","tags":[]},{"id":"poem-ea1b4b13efe418f3722636b5","title":"曲池陪宴即事上窦中丞","author":"熊孺登","dynasty":"唐","verses":["水自山阿绕坐来，珊瑚台上木绵开。","欲知举目无情罚，一片花流酒一杯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-ea08d350-3d1f-46a0-934f-3dffd9c5df36","tags":[]},{"id":"poem-ea1ed64190f2ec50ce852e20","title":"诉衷情·得抽头处好抽头","author":"曹勋","dynasty":"宋","verses":["得抽头处好抽头。","等待几时休。","贤且广张四至，我早已优游。","黄道服，布钱绉。","煞风流。","往来熟后，也没惊怕，也没忧愁。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-156","tags":[]},{"id":"poem-ea211a998614a7fcbf3bd830","title":"游长宁公主流杯池二十五首 十二","author":"上官昭容","dynasty":"唐","verses":["放旷出烟云，萧条自不群。","漱流清意府，隐几避嚻氛。","石画妆苔色，风梭织水文。","山室何为贵？唯余兰桂熏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-5c9271d7-7837-4f32-ac69-2d78708665f6","tags":[]},{"id":"poem-ea225a8821d012e4dfb7678b","title":"句","author":"李绅","dynasty":"唐","verses":["君咏风月夕，余当童稚年。","闲窗读书罢，偷咏左司篇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-8a7e5945-d571-4c50-b620-634872d6d893","tags":[]},{"id":"poem-ea363d21b0ff215873f91ea5","title":"大雨","author":"杜甫","dynasty":"唐","verses":["西蜀冬不雪，春农尚嗷嗷。","上天回哀眷，朱夏云郁陶。","执热乃沸鼎，纤𫄨成缊袍。","风雷飒万里，霈泽施蓬蒿。","敢辞茅苇漏，已喜黍豆高。","三日无行人，二江声怒号。","流恶邑里清，矧兹远江臯。","荒庭步鹳鹤，隐几望波涛。","沈疴聚药饵，顿忘所进劳。","则知润物功，可以贷不毛。","阴色静陇亩，劝耕自官曹。","四邻耒耜出，何必吾家操。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-3dc49c20-317b-4ef3-9b79-8229b5925fd9","tags":[]},{"id":"poem-ea3f387a8ece2eed14c3e4d7","title":"隋宫","author":"李商隐","dynasty":"唐","verses":["乘兴南游不戒严，九重谁省谏书函。","春风举国裁宫锦，半作障泥半作帆。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-91f95b30-c42f-470a-9df8-dd6284fca474","tags":["唐诗三百首","七言绝句","咏史怀古","讽刺"]},{"id":"poem-ea408c7bf355e3b2eabcc1b0","title":"菩萨蛮·馀霞收尽寒烟绿","author":"李弥逊","dynasty":"宋","verses":["馀霞收尽寒烟绿。","江山一片团明玉。","敧枕画楼风。","愁生草际蛩。","金茎秋未老。","两鬓吴霜早。","忍负广寒期。","清尊对语谁。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-17","tags":[]},{"id":"poem-ea4416ea2251386e34183e1d","title":"转调蝶恋花・蝶恋花·渐近朱门香夹道","author":"沈蔚","dynasty":"宋","verses":["渐近朱门香夹道。","一片笙歌，依约楼台杪。","野色和烟满芳草。","溪光曲曲山回抱。","物华不逐人间老。","日日春风，在处花枝好。","莫恨云深路难到。","刘郎可惜归来早。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-988","tags":[]},{"id":"poem-ea4fcafdcee45861d77bd268","title":"汤泉应制·身向咸池榜末光","author":"纳兰性德","dynasty":"清","verses":["身向咸池榜末光，三危露暖不成霜。","金铺照日初涵影，玉求生烟别作香。","地接蓬莱通御气，波翻豆蔻散朝凉。","微臣幸属赓歌日，愿借如川献寿觞。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-245","tags":[]},{"id":"poem-ea5130a150d416dd71208309","title":"送池阳徐守","author":"殷文圭","dynasty":"唐","verses":["四时风雨随旌旗，八面溪山捧郡楼。","（见《舆地纪胜》卷二十二《池州》。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-ba3bb30e-90ac-4d24-b570-7e591abc391f","tags":[]},{"id":"poem-ea561db6e466f13f24e66972","title":"嘉陵江","author":"薛逢","dynasty":"唐","verses":["备问嘉陵江水湄，百川东去尔西之。","但教清浅源流在，天路朝宗会有期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-1d2a89fa-22d5-4234-9887-3fbf2d63f419","tags":[]},{"id":"poem-ea5a72d8c1c0e5bff48d2336","title":"上吏部崔相公","author":"薛逢","dynasty":"唐","verses":["龙门曾共战惊澜，雷电浮云出濬湍。","紫府有名同羽化，碧霄无路却泥蟠。","公车未结王生袜，客路虚弹贡禹冠。","今日罏锤任真宰，暂回风水不应难。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-1784cb92-b5fb-4807-9534-e4e1bef1bed1","tags":[]},{"id":"poem-ea5ac7793180170e1c14e16e","title":"曲游春·楚苑东风外","author":"周密","dynasty":"宋","verses":["楚苑东风外，暖丝情絮，春思如织。","燕约莺期，恼芳情偏在，翠深红隙。","漠漠香尘隔。","沸十里、乱弦丛笛。","看画船，尽入西泠，闲却半湖春色。","柳陌。","新烟凝碧。","映帘底宫眉，堤上游勒。","轻暝笼寒，怕梨云梦冷，杏香愁幂。","歌管酬寒食。","奈蝶怨、良宵岑寂。","正满湖、碎月摇花，怎生去得。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-96","tags":["宋词三百首"]},{"id":"poem-ea5c47ed32bd0f8673dbf084","title":"秋望","author":"李咸用","dynasty":"唐","verses":["云阴惨澹柳阴稀，游子天涯一望时。","风闪雁行疎又密，地回江势急还迟。","荣枯物理终难测，贵贱人生自不知。","未达谁能多叹息，尘埃争损得男儿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-6ae7f452-3573-4dac-8db4-11f0d6c266c0","tags":[]},{"id":"poem-ea63e142a37d5ce796b66333","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［旦］想前生曾结分缘，与才郎共成姻眷。","喜得他脱白挂绿，怕嫌奴体微名贱。","若得他贫相守，富相连，心不变，死而无怨。","［合前］。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8178","tags":[]},{"id":"poem-ea65ebce5896378775a3ea11","title":"送郑侍御谪闽中","author":"高适","dynasty":"唐","verses":["谪去君无恨，闽中我旧过。","大都秋雁少，只是夜猿多。","东路云山合，南天瘴疠和。","自当逢雨露，行矣顺风波。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-送鄭侍御謫閩中","tags":[]},{"id":"poem-ea6852192975c71e60752fb5","title":"减字木兰花·葛山仙隐","author":"葛胜仲","dynasty":"宋","verses":["葛山仙隐。","尚有馀膏留旧鼎。","十里梅花。","夹道争看衮绣华。","人间妙丽。","并侍黄扉开国贵。","僻壤孤芳。","羞涩尊前不敢香。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-18","tags":[]},{"id":"poem-ea69a6b0a05ba2d27b012abb","title":"寄题建安公梅山堂","author":"张栻","dynasty":"宋","verses":["梅公山色近庭除，胜日供公几杖余。","千古谩传栖迹地，当年谁忆爱君书。","丹心炯炯元无间，白发星星不用鉏。","待得斯民俱奠枕，归来端亦爱吾庐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-f06bb592-ae70-4421-b951-ac6b6b977f17","tags":[]},{"id":"poem-ea7a43c4a331c87489c23c27","title":"题曾氏山园十一咏 夕阳台","author":"张栻","dynasty":"宋","verses":["日暮天无风，岸巾夕阳中。","回首发遐想，明月已升东。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-169a700a-f5f0-4d6e-9152-d19ba410b26e","tags":[]},{"id":"poem-ea8709f92ccaaaeffcc517cc","title":"宿宣义池亭","author":"刘得仁","dynasty":"唐","verses":["暮色遶柯亭，南山幽竹青。","夜深斜舫月，风定一池星。","岛屿无人迹，菰蒲有鹤翎。","此中足吟眺，何用泛沧溟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-f7cc5d03-dbca-4ec7-9fc3-5c31a33d9bac","tags":[]},{"id":"poem-ea8a05abeb2395a1beedcd1b","title":"更漏子·锦筵红","author":"张先","dynasty":"宋","verses":["锦筵红，罗幕翠。","侍宴美人姝丽。","十五六，解怜才。","劝人深酒杯。","黛眉长，檀口小。","耳畔向人轻道。","柳阴曲，是儿家。","门前红杏花。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-314","tags":[]},{"id":"poem-ea8a970b2da62e974f86f2ff","title":"田家二首 一","author":"聂夷中","dynasty":"唐","verses":["父耕原上田，子㔉山下荒。","六月禾未秀，官家已修仓。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-91276d5a-1844-40ec-a102-a41eaab21c12","tags":["忧国忧民","讽刺"]},{"id":"poem-ea9373b56eb3ab4f306b93fd","title":"奉和九月九日登慈恩寺浮图应制","author":"毕干泰","dynasty":"唐","verses":["鹦林花塔启，凤辇顺时游。","重九昭皇庆，大千扬帝休。","耆阇妙法阐，王舍睿文流。","至德覃无极，小臣歌讵酬。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-3654c63d-a93d-41b3-aa3b-3b1d7387eb97","tags":[]}];
